window.HEALTHAI_UNITS = [{"id":"unit-1","roman":"I","title":"Introduction to AI in Healthcare","focus":"Foundations of AI in medicine, CDSS, the clinical data ecosystem, specialty applications, telemedicine","chapters":[{"n":1,"slug":"ch-01","title":"Foundations of Healthcare AI: Definition, Evolution, Scope"},{"n":2,"slug":"ch-02","title":"Traditional vs AI-Enabled Healthcare Workflows"},{"n":3,"slug":"ch-03","title":"Clinical Decision Support Systems (CDSS)"},{"n":4,"slug":"ch-04","title":"The Medical Data Ecosystem"},{"n":5,"slug":"ch-05","title":"EHRs vs Paper-Based Records"},{"n":6,"slug":"ch-06","title":"Specialty Applications: Radiology, Pathology, Oncology, Cardiology"},{"n":7,"slug":"ch-07","title":"Diagnosis, Prognosis, and Patient Monitoring"},{"n":8,"slug":"ch-08","title":"Telemedicine and Deployment Challenges"}]},{"id":"unit-2","roman":"II","title":"Data Preprocessing and Feature Engineering in Clinical Datasets","focus":"Cleaning, missing data and bias, EHR and time-series features, dimensionality reduction, clinical NLP, ICD/CPT","chapters":[{"n":9,"slug":"ch-09","title":"Clinical Data Cleaning, Normalization, and Standardization"},{"n":10,"slug":"ch-10","title":"Missing Values, Outliers, and Collection Bias"},{"n":11,"slug":"ch-11","title":"Feature Engineering for EHR Data"},{"n":12,"slug":"ch-12","title":"Physiological Time-Series Features and Dimensionality Reduction"},{"n":13,"slug":"ch-13","title":"Text Mining and NLP for Clinical Notes"},{"n":14,"slug":"ch-14","title":"ICD and CPT Coding Systems"}]},{"id":"unit-3","roman":"III","title":"Machine Learning & Deep Learning for Healthcare Analytics","focus":"Supervised and unsupervised learning, CNNs and transfer learning, RNNs/LSTMs, evaluation metrics, imbalance, LIME/SHAP, HIPAA","chapters":[{"n":15,"slug":"ch-15","title":"Supervised Learning for Risk Prediction and Diagnostic Classification"},{"n":16,"slug":"ch-16","title":"Unsupervised Learning: Stratification, Phenotyping, Anomaly Detection"},{"n":17,"slug":"ch-17","title":"CNNs and Transfer Learning for Medical Imaging"},{"n":18,"slug":"ch-18","title":"RNNs/LSTMs for Clinical Time Series"},{"n":19,"slug":"ch-19","title":"Evaluation Metrics: Sensitivity, Specificity, AUC-ROC, Precision, F1"},{"n":20,"slug":"ch-20","title":"Imbalanced Healthcare Datasets: Rare Disease Detection"},{"n":21,"slug":"ch-21","title":"Explainable AI: LIME and SHAP"},{"n":22,"slug":"ch-22","title":"Privacy, Anonymization, and HIPAA"}]},{"id":"unit-4","roman":"IV","title":"Specialized AI Applications & Clinical Implementation","focus":"Disease diagnosis, multi-modal systems, segmentation, ICU analytics, genomics, drug discovery, digital health","chapters":[{"n":23,"slug":"ch-23","title":"AI in Disease Diagnosis: Diabetes, Cancer, Heart Disease"},{"n":24,"slug":"ch-24","title":"Multi-Modal AI Systems"},{"n":25,"slug":"ch-25","title":"Advanced Medical Image Analysis: Detection and Segmentation"},{"n":26,"slug":"ch-26","title":"Predictive Analytics in Critical Care (ICU)"},{"n":27,"slug":"ch-27","title":"Genomics, Pharmacogenomics, and Personalized Medicine"},{"n":28,"slug":"ch-28","title":"AI-Driven Drug Discovery and Repurposing"},{"n":29,"slug":"ch-29","title":"Digital Health: Chatbots, Virtual Assistants, IoT, and Wearables"}]},{"id":"unit-5","roman":"V","title":"Ethics, Governance & Regulatory Landscape","focus":"Bioethics, bias and fairness, FDA/CE for SaMD, responsible deployment, XAI and trust, federated learning, clinical trials","chapters":[{"n":30,"slug":"ch-30","title":"Bioethical Principles and Ethical Frameworks for Healthcare AI"},{"n":31,"slug":"ch-31","title":"Bias, Fairness, and Health Equity"},{"n":32,"slug":"ch-32","title":"Regulatory Landscape: FDA, CE Marking, and SaMD"},{"n":33,"slug":"ch-33","title":"Responsible Deployment and Governance"},{"n":34,"slug":"ch-34","title":"Explainable AI and Building Clinical Trust"},{"n":35,"slug":"ch-35","title":"Federated Learning and Privacy-Preserving AI"},{"n":36,"slug":"ch-36","title":"Clinical Validation, Trials, and the Future of Healthcare AI"}]}];

window.HEALTHAI_SEARCH = [{"type":"page","title":"Contents","kicker":"All units and chapters","url":"contents.html","text":"Full table of contents"},{"type":"page","title":"Glossary","kicker":"Appendix A","url":"glossary.html","text":"Key terms and definitions"},{"type":"page","title":"Lab manual","kicker":"Appendix B","url":"labs.html","text":"Eight lab exercises and datasets"},{"type":"page","title":"Further reading","kicker":"Appendix C","url":"reading.html","text":"Reference list"},{"type":"page","title":"Question bank","kicker":"Appendix D","url":"question-bank.html","text":"Exam practice questions"},{"type":"chapter","title":"Foundations of Healthcare AI: Definition, Evolution, Scope","kicker":"Unit I · Chapter 01","url":"read/ch-01.html","text":"Define Artificial Intelligence in Healthcare precisely and separate AI, machine learning, and deep learning in a medical context. 1.1 Chapter objectives 1.2 Definition 1.3 Evolution — four generations 1.4 Scope across the patient journey 1.5 What this book does not cover 1.6 Key terms 1.7 Review questions"},{"type":"section","title":"1.1 Chapter objectives","kicker":"Chapter 01 · Foundations of Healthcare AI: Definition, Evolution, Scope","url":"read/ch-01.html#s-1-1","text":"Define Artificial Intelligence in Healthcare precisely and separate AI, machine learning, and deep learning in a medical context. Trace the evolution of the field through four distinct generations of technology. State the scope of healthcare AI across the patient journey, from triage to outcome tracking."},{"type":"section","title":"1.2 Definition","kicker":"Chapter 01 · Foundations of Healthcare AI: Definition, Evolution, Scope","url":"read/ch-01.html#s-1-2","text":"AI in Healthcare is the application of computational systems that perceive clinical data, learn patterns from it, and act or recommend in ways that support (or, in narrow tasks, replace) human medical decision-making. The nesting matters: artificial intelligence is the umbrella; machine learning is the subset that learns from data rather than being explicitly programmed; deep learning is the subse"},{"type":"section","title":"1.3 Evolution — four generations","kicker":"Chapter 01 · Foundations of Healthcare AI: Definition, Evolution, Scope","url":"read/ch-01.html#s-1-3","text":"Generation Era Technology Landmark examples Symbolic / rule-based 1970s–1990s Hand-coded expert rules, Bayesian reasoning MYCIN (antibiotic selection, ~69% acceptable-therapy rate in evaluation), INTERNIST-I, early expert systems Statistical ML 1990s–2010s Logistic regression, SVMs, survival models on structured data Administrative claims risk models, early CAD (computer-aided detection) in mammog"},{"type":"section","title":"1.4 Scope across the patient journey","kicker":"Chapter 01 · Foundations of Healthcare AI: Definition, Evolution, Scope","url":"read/ch-01.html#s-1-4","text":"Healthcare AI now touches: triage and scheduling (symptom checkers, capacity forecasting), diagnosis (imaging, pathology, ECG interpretation), treatment planning (radiotherapy contouring, drug dosing), monitoring (ICU deterioration prediction, wearable arrhythmia detection), operations (length-of-stay, staffing), administration (coding, billing, claims), and research (drug discovery, trial recruit"},{"type":"section","title":"1.5 What this book does not cover","kicker":"Chapter 01 · Foundations of Healthcare AI: Definition, Evolution, Scope","url":"read/ch-01.html#s-1-5","text":"It does not cover hospital information-system architecture in depth, the mathematics of survival analysis, or country-specific billing law. It treats imaging physics, genomics, and pharmacology as black boxes with the properties that matter for AI."},{"type":"section","title":"1.6 Key terms","kicker":"Chapter 01 · Foundations of Healthcare AI: Definition, Evolution, Scope","url":"read/ch-01.html#s-1-6","text":"AI in Healthcare — computational systems that learn from clinical data to support medical decisions. Machine learning (ML) — algorithms that infer patterns from data rather than following hand-coded rules. Deep learning — multi-layer neural networks that learn features from raw data (pixels, waveforms, text). MYCIN — the canonical 1970s rule-based expert system for antibiotic selection; accurate b"},{"type":"section","title":"1.7 Review questions","kicker":"Chapter 01 · Foundations of Healthcare AI: Definition, Evolution, Scope","url":"read/ch-01.html#s-1-7","text":"Define AI in Healthcare in one sentence, then state how ML and deep learning sit inside that definition. Name the four generations of healthcare AI and one landmark system for each. Why was MYCIN historically important despite never being deployed? What made IDx-DR's scope deliberately narrow, and why did that help its approval?"},{"type":"chapter","title":"Traditional vs AI-Enabled Healthcare Workflows","kicker":"Unit I · Chapter 02","url":"read/ch-02.html","text":"Compare traditional and AI-enabled workflows stage by stage. 2.1 Chapter objectives 2.2 Stage-by-stage comparison 2.3 What changes — and what must not 2.4 Failure modes on both sides 2.5 Key terms 2.6 Review questions"},{"type":"section","title":"2.1 Chapter objectives","kicker":"Chapter 02 · Traditional vs AI-Enabled Healthcare Workflows","url":"read/ch-02.html#s-2-1","text":"Compare traditional and AI-enabled workflows stage by stage. Identify what AI changes (speed, breadth, consistency) and what it must not change (accountability, human oversight). Recognize the characteristic failure modes of each workflow."},{"type":"section","title":"2.2 Stage-by-stage comparison","kicker":"Chapter 02 · Traditional vs AI-Enabled Healthcare Workflows","url":"read/ch-02.html#s-2-2","text":"Workflow stage Traditional healthcare system AI-enabled healthcare system History taking Clinician interview; variable completeness, recall bias Structured intake, symptom checkers, chatbot pre-visit triage; consistent but shallow without context Investigation Clinician orders tests from experience and guidelines CDSS suggests evidence-based order sets; AI flags at-risk patients for specific tests"},{"type":"section","title":"2.3 What changes — and what must not","kicker":"Chapter 02 · Traditional vs AI-Enabled Healthcare Workflows","url":"read/ch-02.html#s-2-3","text":"AI changes speed (milliseconds vs human reading), breadth (every patient, every study, every hour), and consistency (no fatigue, no inter-observer variation). It must not change accountability : the clinician remains responsible for the decision, and regulation (Unit V) is written around that. The safe pattern is AI proposes, human disposes — with autonomy granted only in narrow, well-validated, l"},{"type":"section","title":"2.4 Failure modes on both sides","kicker":"Chapter 02 · Traditional vs AI-Enabled Healthcare Workflows","url":"read/ch-02.html#s-2-4","text":"Traditional: knowledge decay, missed findings from fatigue, inter-observer variability (radiologists disagree on a meaningful fraction of studies), access inequity (expertise concentrated in cities). AI-enabled: dataset shift (a model trained in hospital A underperforms in hospital B), automation bias (clinicians accepting machine suggestions uncritically), alert fatigue, silent failure when input"},{"type":"section","title":"2.5 Key terms","kicker":"Chapter 02 · Traditional vs AI-Enabled Healthcare Workflows","url":"read/ch-02.html#s-2-5","text":"Automation bias — the tendency to over-trust machine output and stop checking. Inter-observer variability — disagreement between experts on the same case. Dataset shift — production data differing statistically from training data. AI proposes, human disposes — the default accountability pattern for clinical AI."},{"type":"section","title":"2.6 Review questions","kicker":"Chapter 02 · Traditional vs AI-Enabled Healthcare Workflows","url":"read/ch-02.html#s-2-6","text":"Compare traditional and AI-enabled workflows across three stages of your choice. Which property of AI (speed, breadth, consistency) most directly addresses inter-observer variability, and why? Define automation bias and give one safeguard against it in a radiology workflow."},{"type":"chapter","title":"Clinical Decision Support Systems (CDSS)","kicker":"Unit I · Chapter 03","url":"read/ch-03.html","text":"Define CDSS and describe its four architectural components. 3.1 Chapter objectives 3.2 Definition and architecture 3.3 Knowledge-based vs non-knowledge-based CDSS 3.4 The five rights of CDS 3.5 Real examples 3.6 Key terms 3.7 Review questions"},{"type":"section","title":"3.1 Chapter objectives","kicker":"Chapter 03 · Clinical Decision Support Systems (CDSS)","url":"read/ch-03.html#s-3-1","text":"Define CDSS and describe its four architectural components. Distinguish knowledge-based from non-knowledge-based (analytic/ML) CDSS. Apply the \"five rights\" of clinical decision support to a real example."},{"type":"section","title":"3.2 Definition and architecture","kicker":"Chapter 03 · Clinical Decision Support Systems (CDSS)","url":"read/ch-03.html#s-3-2","text":"A Clinical Decision Support System (CDSS) is a computer-based system that assists clinical decision-making by presenting patient-specific information and/or knowledge-based recommendations to clinicians at the point of care. Its four components: ┌──────────────────┐ ┌─────────────────────┐ ┌──────────────────┐ │ Patient data │ │ Inference engine │ │ Communication / │ │ EHR · labs · │ ──► │ rules ·"},{"type":"section","title":"3.3 Knowledge-based vs non-knowledge-based CDSS","kicker":"Chapter 03 · Clinical Decision Support Systems (CDSS)","url":"read/ch-03.html#s-3-3","text":"Knowledge-based: encoded rules from guidelines and literature. Transparent and auditable; brittle and expensive to maintain, blind to what nobody encoded. Classic example: drug–drug interaction alerts. Non-knowledge-based (analytic/ML): models learned from patient data — logistic regression for mortality, neural networks for sepsis hours ahead, random forests for readmission. Adapts to local data;"},{"type":"section","title":"3.4 The five rights of CDS","kicker":"Chapter 03 · Clinical Decision Support Systems (CDSS)","url":"read/ch-03.html#s-3-4","text":"Effective decision support must deliver: the right information , to the right person , in the right interventional format , through the right channel , at the right time in the workflow . Most CDSS failures are interface failures, not accuracy failures — an accurate sepsis model that fires 200 alerts a day is operationally worthless."},{"type":"section","title":"3.5 Real examples","kicker":"Chapter 03 · Clinical Decision Support Systems (CDSS)","url":"read/ch-03.html#s-3-5","text":"Drug safety: a new prescription triggers an interaction check against the medication list; the knowledge base is curated, the logic is a rule match. Sepsis early warning: an ML model scores every admitted patient hourly from vitals and labs; a rising score pages a rapid-response team (deployment lessons from Epic's widely deployed sepsis model — high sensitivity at the cost of a large false-alarm "},{"type":"section","title":"3.6 Key terms","kicker":"Chapter 03 · Clinical Decision Support Systems (CDSS)","url":"read/ch-03.html#s-3-6","text":"CDSS — patient-specific, point-of-care decision support software. Knowledge base / inference engine — stored medical knowledge / the logic that applies it to a patient. Five rights of CDS — right information, person, format, channel, time. Alert fatigue — desensitization caused by excessive low-value alerts."},{"type":"section","title":"3.7 Review questions","kicker":"Chapter 03 · Clinical Decision Support Systems (CDSS)","url":"read/ch-03.html#s-3-7","text":"Draw the four-component CDSS architecture and place a learned sepsis model inside it. Contrast knowledge-based and ML-based CDSS on transparency, maintenance, and adaptability. Apply the five rights to an interruptive drug-interaction alert. Why is alert burden, not model accuracy, the usual determinant of whether a CDSS survives?"},{"type":"chapter","title":"The Medical Data Ecosystem","kicker":"Unit I · Chapter 04","url":"read/ch-04.html","text":"Enumerate the major clinical data types and their structure, standards, and AI uses. 4.1 Chapter objectives 4.2 The data types 4.3 Standards that hold it together 4.4 Shared challenges 4.5 Key terms 4.6 Review questions"},{"type":"section","title":"4.1 Chapter objectives","kicker":"Chapter 04 · The Medical Data Ecosystem","url":"read/ch-04.html#s-4-1","text":"Enumerate the major clinical data types and their structure, standards, and AI uses. Explain the standards that make the ecosystem interoperable (HL7/FHIR, DICOM, FASTQ/VCF). Recognize the shared data challenges: silos, quality, sparsity, and privacy."},{"type":"section","title":"4.2 The data types","kicker":"Chapter 04 · The Medical Data Ecosystem","url":"read/ch-04.html#s-4-2","text":"Data type Structure & standards What it looks like Typical AI uses Electronic Health Records (EHR) Semi-structured; relational schemas; HL7 v2 / FHIR resources Demographics, encounters, medications, orders, lab results (LOINC-coded) Risk prediction, readmission, deterioration, phenotyping Medical imaging Pixels + metadata; DICOM standard; PACS storage X-ray, CT, MRI, ultrasound, whole-slide pathol"},{"type":"section","title":"4.3 Standards that hold it together","kicker":"Chapter 04 · The Medical Data Ecosystem","url":"read/ch-04.html#s-4-3","text":"HL7 v2 / FHIR (Fast Healthcare Interoperability Resources): message and resource standards for clinical data exchange; FHIR models data as discrete resources (Patient, Observation, MedicationRequest) addressable by API. DICOM (Digital Imaging and Communications in Medicine): the imaging standard — pixel data plus a rich metadata header (patient, acquisition parameters, window settings). PACS = Pic"},{"type":"section","title":"4.4 Shared challenges","kicker":"Chapter 04 · The Medical Data Ecosystem","url":"read/ch-04.html#s-4-4","text":"Silos and fragmentation: one patient's story is spread across institutions, none of which can legally or technically merge it freely (hence federated learning, Chapter 35). Quality and messiness: missing values, unit inconsistencies (mg/dL vs mmol/L), duplicate records, copy-forward notes. Sparsity and skew: rare diseases have few positive examples; lab tests are ordered non-randomly (a \"missing\" "},{"type":"section","title":"4.5 Key terms","kicker":"Chapter 04 · The Medical Data Ecosystem","url":"read/ch-04.html#s-4-5","text":"EHR — longitudinal digital record of patient encounters, orders, results, medications. DICOM / PACS — imaging data standard / the archive system for it. FASTQ / VCF — raw sequencing reads / called variants. ECG / EEG / PPG — heart electrical, brain electrical, pulse waveform signals. HL7 FHIR — modern web-style clinical data exchange standard. LOINC / SNOMED CT / RxNorm — lab, clinical-term, and m"},{"type":"section","title":"4.6 Review questions","kicker":"Chapter 04 · The Medical Data Ecosystem","url":"read/ch-04.html#s-4-6","text":"List five clinical data types, their standards, and one AI application each. What do FHIR resources and DICOM headers have in common, and why does metadata matter for imaging ML? Why can a \"missing\" lab value carry clinical meaning, and what does that imply for preprocessing (preview of Chapter 10)?"},{"type":"chapter","title":"EHRs vs Paper-Based Records","kicker":"Unit I · Chapter 05","url":"read/ch-05.html","text":"Compare EHRs and paper records across accessibility, structure, cost, and legal dimensions. 5.1 Chapter objectives 5.2 Comparison 5.3 Why computability is the decisive property 5.4 The EHR's own failure modes 5.5 Key terms 5.6 Review questions"},{"type":"section","title":"5.1 Chapter objectives","kicker":"Chapter 05 · EHRs vs Paper-Based Records","url":"read/ch-05.html#s-5-1","text":"Compare EHRs and paper records across accessibility, structure, cost, and legal dimensions. Explain why computability (not storage) is the decisive difference for AI. Name the EHR's own new failure modes."},{"type":"section","title":"5.2 Comparison","kicker":"Chapter 05 · EHRs vs Paper-Based Records","url":"read/ch-05.html#s-5-2","text":"Dimension Paper-based records Electronic Health Records Accessibility One physical copy; single-site access; can be lost Multi-site, multi-user simultaneous access; backup and audit trails Legibility Handwriting varies; transcription errors Structured coded data (ICD, LOINC); typed notes Search & analysis Manual chart review; infeasible at scale Queryable at scale; the substrate for machine learni"},{"type":"section","title":"5.3 Why computability is the decisive property","kicker":"Chapter 05 · EHRs vs Paper-Based Records","url":"read/ch-05.html#s-5-3","text":"A paper chart is readable ; an EHR is computable . Three consequences for AI: (1) structured fields (coded diagnoses, lab values with units and timestamps) become training data directly; (2) longitudinal histories become time series rather than prose; (3) the same computable record that feeds a model also feeds decision support at the bedside. AI in healthcare is, in a precise sense, a consequence"},{"type":"section","title":"5.4 The EHR's own failure modes","kicker":"Chapter 05 · EHRs vs Paper-Based Records","url":"read/ch-05.html#s-5-4","text":"Note-bloat and copy-forward (propagated stale information), template-driven notes that bury signal, alert overload from naive CDS, usability burden (clinician time in the EHR is a documented burnout driver), and data-entry errors that ML models then faithfully learn. Preprocessing (Unit II) exists largely because of these."},{"type":"section","title":"5.5 Key terms","kicker":"Chapter 05 · EHRs vs Paper-Based Records","url":"read/ch-05.html#s-5-5","text":"EHR — longitudinal, computable, digital patient record shared across care settings. Computability — the property that data can be queried and processed algorithmically, not just read. Copy-forward — copying prior note text forward, propagating stale information."},{"type":"section","title":"5.6 Review questions","kicker":"Chapter 05 · EHRs vs Paper-Based Records","url":"read/ch-05.html#s-5-6","text":"Give four dimensions on which EHRs improve on paper records, and one on which they introduce a new risk. Explain why AI in healthcare is described as \"a consequence of the EHR transition\"."},{"type":"chapter","title":"Specialty Applications: Radiology, Pathology, Oncology, Cardiology","kicker":"Unit I · Chapter 06","url":"read/ch-06.html","text":"Describe the flagship AI applications in radiology, pathology, oncology, and cardiology. 6.1 Chapter objectives 6.2 Radiology — detection and triage on pixels 6.3 Pathology — gigapixel whole-slide imaging 6.4 Oncology — longitudinal prognosis and treatment planning 6.5 Cardiology — waveform interpretation at scale 6.6 Specialty comparison and barriers 6.7 Key terms 6.8 Review questions"},{"type":"section","title":"6.1 Chapter objectives","kicker":"Chapter 06 · Specialty Applications: Radiology, Pathology, Oncology, Cardiology","url":"read/ch-06.html#s-6-1","text":"Describe the flagship AI applications in radiology, pathology, oncology, and cardiology. Connect each application to its data substrate and its evaluation method. Identify the specialty-specific adoption barriers."},{"type":"section","title":"6.2 Radiology — detection and triage on pixels","kicker":"Chapter 06 · Specialty Applications: Radiology, Pathology, Oncology, Cardiology","url":"read/ch-06.html#s-6-2","text":"Radiology was the first AI beachhead because imaging was already digital (DICOM/PACS). Flagship tasks: chest X-ray findings (pneumonia, pneumothorax, consolidation), CT intracranial hemorrhage triage, mammography (screening support; large 2020s trials showed AI-supported reading matched or exceeded double reading in reduction of workload and comparable cancer detection), lung-nodule detection on l"},{"type":"section","title":"6.3 Pathology — gigapixel whole-slide imaging","kicker":"Chapter 06 · Specialty Applications: Radiology, Pathology, Oncology, Cardiology","url":"read/ch-06.html#s-6-3","text":"Digital pathology converts glass slides into whole-slide images (WSI) — gigapixel, multi-gigabyte. Tasks: mitosis detection, tumor grading (e.g., Gleason grading of prostate), lymph-node metastasis detection (the CAMELYON16 challenge), biomarker quantification (IHC scoring). Constraints: staining and scanner variability (models must be stain-normalized or robust), no single-cell ground truth, and "},{"type":"section","title":"6.4 Oncology — longitudinal prognosis and treatment planning","kicker":"Chapter 06 · Specialty Applications: Radiology, Pathology, Oncology, Cardiology","url":"read/ch-06.html#s-6-4","text":"Oncology AI spans: cancer detection (imaging, pathology), prognosis (survival models from EHR + tumor features), treatment recommendation (precision oncology: matching tumor genomics to targeted therapies; radiotherapy auto-contouring of organs at risk, now routinely deployed), and trial matching. Data is longitudinal and multi-modal; ground truth (recurrence, survival) takes years — the core eval"},{"type":"section","title":"6.5 Cardiology — waveform interpretation at scale","kicker":"Chapter 06 · Specialty Applications: Radiology, Pathology, Oncology, Cardiology","url":"read/ch-06.html#s-6-5","text":"Cardiology's substrate is the ECG and the echocardiogram. Landmark capabilities: deep models classifying 12-lead ECGs across dozens of rhythms at cardiologist-level performance (Stanford/Mayo work), AF detection from single-lead PPG in consumer wearables (Apple Heart Study), and AI estimation of ejection fraction from echo videos. Cardiology AI also pioneered phenotype-from-ECG : models inferring "},{"type":"section","title":"6.6 Specialty comparison and barriers","kicker":"Chapter 06 · Specialty Applications: Radiology, Pathology, Oncology, Cardiology","url":"read/ch-06.html#s-6-6","text":"Specialty Data substrate Flagship task Key barrier Radiology DICOM pixels Detection/triage Worklist integration; liability for misses Pathology WSI gigapixels Grading/quantification Stain/scanner variability; slide digitization cost Oncology Longitudinal multi-modal Prognosis/treatment match Slow-moving ground truth; genomics access Cardiology ECG/echo signals Rhythm/functional classification Cons"},{"type":"section","title":"6.7 Key terms","kicker":"Chapter 06 · Specialty Applications: Radiology, Pathology, Oncology, Cardiology","url":"read/ch-06.html#s-6-7","text":"WSI (whole-slide imaging) — gigapixel digital scan of a pathology slide. Gleason grading — prostate cancer aggressiveness grading from tissue architecture. CADe / CADx — computer-aided detection / diagnosis. Ejection fraction (EF) — fraction of blood ejected per heartbeat; the echo AI headline target. Precision oncology — therapy selection driven by tumor molecular profile."},{"type":"section","title":"6.8 Review questions","kicker":"Chapter 06 · Specialty Applications: Radiology, Pathology, Oncology, Cardiology","url":"read/ch-06.html#s-6-8","text":"Why did radiology and cardiology adopt AI earlier than oncology? What is stain variability and why does it matter for pathology ML? Name one deployed oncology AI task whose ground truth is slow and one whose ground truth is fast."},{"type":"chapter","title":"Diagnosis, Prognosis, and Patient Monitoring","kicker":"Unit I · Chapter 07","url":"read/ch-07.html","text":"Define diagnosis, prognosis, and monitoring as distinct AI tasks with distinct data and error costs. 7.1 Chapter objectives 7.2 Diagnosis — classifying the present state 7.3 Prognosis — predicting the future trajectory 7.4 Monitoring — the continuous case 7.5 Key terms 7.6 Review questions"},{"type":"section","title":"7.1 Chapter objectives","kicker":"Chapter 07 · Diagnosis, Prognosis, and Patient Monitoring","url":"read/ch-07.html#s-7-1","text":"Define diagnosis, prognosis, and monitoring as distinct AI tasks with distinct data and error costs. Give a flagship example and a failure mode for each. Explain why monitoring is where AI has its largest scale advantage."},{"type":"section","title":"7.2 Diagnosis — classifying the present state","kicker":"Chapter 07 · Diagnosis, Prognosis, and Patient Monitoring","url":"read/ch-07.html#s-7-2","text":"Diagnosis assigns a present condition from evidence. AI tasks: image classification (pneumonia vs normal), multiclass differential support (rash triage), lab-pattern recognition (sepsis). Data is cross-sectional (the study at hand plus history). Error costs are asymmetric and task-specific: a missed cancer (false negative) is catastrophic; a false positive costs a follow-up procedure. Diagnosis AI"},{"type":"section","title":"7.3 Prognosis — predicting the future trajectory","kicker":"Chapter 07 · Diagnosis, Prognosis, and Patient Monitoring","url":"read/ch-07.html#s-7-3","text":"Prognosis predicts future outcomes: mortality, readmission, recurrence, disease progression. Data is longitudinal; labels arrive with delay and censoring (a patient lost to follow-up has an unknown label). Methods range from classical survival analysis (Cox models) to deep survival networks. Prognosis is where EHR breadth pays: models fuse labs, comorbidities, and utilization history. Its danger i"},{"type":"section","title":"7.4 Monitoring — the continuous case","kicker":"Chapter 07 · Diagnosis, Prognosis, and Patient Monitoring","url":"read/ch-07.html#s-7-4","text":"Monitoring applies the diagnosis/prognosis logic continuously: ICU deterioration prediction (hours-ahead sepsis or decompensation warnings), ward early-warning scores (the classical NEWS score vs learned models), arrhythmia screening on wearables, glucose forecasting for insulin dosing. AI's advantage is scale and vigilance: it watches every patient every minute, catching the slow decline a roundi"},{"type":"section","title":"7.5 Key terms","kicker":"Chapter 07 · Diagnosis, Prognosis, and Patient Monitoring","url":"read/ch-07.html#s-7-5","text":"Diagnosis — classification of the patient's present condition. Prognosis — prediction of a future clinical outcome. Monitoring / early warning — continuous prediction of imminent deterioration. Censoring — unknown outcomes for patients lost to observation (a survival-analysis concept)."},{"type":"section","title":"7.6 Review questions","kicker":"Chapter 07 · Diagnosis, Prognosis, and Patient Monitoring","url":"read/ch-07.html#s-7-6","text":"Contrast diagnosis and prognosis on data type, label timing, and error cost. Why is monitoring where AI's scale advantage is largest, and what failure mode comes with it? What is censoring and why does it complicate prognosis model training?"},{"type":"chapter","title":"Telemedicine and Deployment Challenges","kicker":"Unit I · Chapter 08","url":"read/ch-08.html","text":"Describe AI's roles in telemedicine platforms and remote care delivery. 8.1 Chapter objectives 8.2 AI in telemedicine and remote care 8.3 The deployment challenges (the honest list) 8.4 Key terms 8.5 Review questions"},{"type":"section","title":"8.1 Chapter objectives","kicker":"Chapter 08 · Telemedicine and Deployment Challenges","url":"read/ch-08.html#s-8-1","text":"Describe AI's roles in telemedicine platforms and remote care delivery. List the operational and data-driven challenges of healthcare AI deployment. Connect each challenge to the unit of this book that addresses it."},{"type":"section","title":"8.2 AI in telemedicine and remote care","kicker":"Chapter 08 · Telemedicine and Deployment Challenges","url":"read/ch-08.html#s-8-2","text":"Intake and triage: symptom-checker chatbots and structured intake route patients to the right level of care before a video visit. Visit augmentation: ambient documentation (AI drafting the visit note from the conversation), real-time transcription, and language translation broaden access. Remote patient monitoring (RPM): wearables and home devices stream vitals; AI models watch trajectories and es"},{"type":"section","title":"8.3 The deployment challenges (the honest list)","kicker":"Chapter 08 · Telemedicine and Deployment Challenges","url":"read/ch-08.html#s-8-3","text":"Data quality and fragmentation — telemedicine data is sparse, self-reported, device-generated; models trained on in-person populations shift (Unit II). Privacy and security — PHI now traverses home networks and consumer devices; HIPAA-compliant channels and vendor agreements are mandatory (Unit III). Interpretability and trust — a remote recommendation with no visible reasoning is hard for a clini"},{"type":"section","title":"8.4 Key terms","kicker":"Chapter 08 · Telemedicine and Deployment Challenges","url":"read/ch-08.html#s-8-4","text":"Telemedicine — remote clinical care via telecommunications, synchronous or store-and-forward. RPM — remote patient monitoring: device-streamed vitals with algorithmic escalation. Ambient documentation — AI-generated visit notes from the consultation audio. Store-and-forward — asynchronous capture-then-read telemedicine."},{"type":"section","title":"8.5 Review questions","kicker":"Chapter 08 · Telemedicine and Deployment Challenges","url":"read/ch-08.html#s-8-5","text":"Name three AI roles in telemedicine and one data-driven challenge each creates. Pick four of the eight deployment challenges and connect each to the chapter that addresses it. The official question bank for this unit — 18 questions with full model answers — is in Appendix D of this book."},{"type":"chapter","title":"Clinical Data Cleaning, Normalization, and Standardization","kicker":"Unit II · Chapter 09","url":"read/ch-09.html","text":"Define data cleaning, normalization, and standardization and state how they differ. 9.1 Chapter objectives 9.2 Data cleaning 9.3 Normalization vs standardization 9.4 What cleaning changes downstream 9.5 Key terms 9.6 Review questions"},{"type":"section","title":"9.1 Chapter objectives","kicker":"Chapter 09 · Clinical Data Cleaning, Normalization, and Standardization","url":"read/ch-09.html#s-9-1","text":"Define data cleaning, normalization, and standardization and state how they differ. Apply the core techniques to clinical examples (lab units, vitals ranges, coded fields). Recognize cleaning decisions that change a model's conclusions."},{"type":"section","title":"9.2 Data cleaning","kicker":"Chapter 09 · Clinical Data Cleaning, Normalization, and Standardization","url":"read/ch-09.html#s-9-2","text":"Data cleaning detects and corrects errors and inconsistencies so the record reflects clinical reality. Core operations in clinical datasets: De-duplication — the same encounter entered twice; the same patient under two identifiers (entity resolution). Unit harmonization — glucose in mg/dL vs mmol/L (factor 18); creatinine mg/dL vs µmol/L (factor 88.4). A dataset mixing units is not a dataset. Rang"},{"type":"section","title":"9.3 Normalization vs standardization","kicker":"Chapter 09 · Clinical Data Cleaning, Normalization, and Standardization","url":"read/ch-09.html#s-9-3","text":"Normalization (min–max scaling) rescales a feature to a bounded range, typically [0, 1]: x' = (x − min)/(max − min) . Used when a bounded scale is required (neural network inputs, image pixel intensities). Sensitive to outliers. Standardization (z-score) rescales to zero mean, unit variance: z = (x − μ)/σ . The default for most tabular ML (SVMs, PCA, regularized regression). Robust variants use me"},{"type":"section","title":"9.4 What cleaning changes downstream","kicker":"Chapter 09 · Clinical Data Cleaning, Normalization, and Standardization","url":"read/ch-09.html#s-9-4","text":"Aggregation results (a mean computed over mixed units is meaningless), outlier detection (an unscaled extreme dominates), model performance (leakage through fitting scalers on all data), and — most subtly — clinical interpretation, because a normalized value has lost its reference range. Keep the raw value alongside the scaled one."},{"type":"section","title":"9.5 Key terms","kicker":"Chapter 09 · Clinical Data Cleaning, Normalization, and Standardization","url":"read/ch-09.html#s-9-5","text":"Data cleaning — detecting and correcting errors/inconsistencies in clinical data. Normalization — rescaling to a bounded range (min–max). Standardization — rescaling to zero mean, unit variance (z-score). Unit harmonization — converting all measurements to a common unit system. Entity resolution — merging records that belong to the same patient/encounter."},{"type":"section","title":"9.6 Review questions","kicker":"Chapter 09 · Clinical Data Cleaning, Normalization, and Standardization","url":"read/ch-09.html#s-9-6","text":"Distinguish cleaning, normalization, and standardization with one clinical example each. Why must a scaler be fitted on training data only? Give two plausibility checks that would catch a data-entry error in vital signs."},{"type":"chapter","title":"Missing Values, Outliers, and Collection Bias","kicker":"Unit II · Chapter 10","url":"read/ch-10.html","text":"Classify missingness (MCAR, MAR, MNAR) and choose an imputation method per class. 10.1 Chapter objectives 10.2 Missing data: three mechanisms 10.3 Imputation methods 10.4 Outliers in clinical data 10.5 Collection and selection bias 10.6 Key terms 10.7 Review questions"},{"type":"section","title":"10.1 Chapter objectives","kicker":"Chapter 10 · Missing Values, Outliers, and Collection Bias","url":"read/ch-10.html#s-10-1","text":"Classify missingness (MCAR, MAR, MNAR) and choose an imputation method per class. Detect and handle outliers without discarding true clinical extremes. Identify collection and selection bias and its impact on model fairness."},{"type":"section","title":"10.2 Missing data: three mechanisms","kicker":"Chapter 10 · Missing Values, Outliers, and Collection Bias","url":"read/ch-10.html#s-10-2","text":"MCAR (Missing Completely At Random) — missingness unrelated to anything observed or unobserved (a dropped network packet). Deletion is nearly unbiased. MAR (Missing At Random) — missingness explainable by observed variables (sicker patients get more blood draws; a test absent because the panel didn't include it). MNAR (Missing Not At Random) — missingness depends on the unobserved value itself (dr"},{"type":"section","title":"10.3 Imputation methods","kicker":"Chapter 10 · Missing Values, Outliers, and Collection Bias","url":"read/ch-10.html#s-10-3","text":"Method How When to use Deletion (listwise) drop incomplete rows MCAR, tiny missing fraction Mean/median/mode fill with central value quick baseline; shrinks variance Last observation carried forward (LOCF) fill with previous value short gaps in dense vitals only KNN imputation fill from similar patients moderate missingness, local structure MICE (chained equations) iterative regression per feature"},{"type":"section","title":"10.4 Outliers in clinical data","kicker":"Chapter 10 · Missing Values, Outliers, and Collection Bias","url":"read/ch-10.html#s-10-4","text":"An outlier is a value far from the distribution. Detection: z-score/IQR rules, isolation forests, clinical plausibility ranges. Handling — and the discipline that matters: first ask whether it is real . A heart rate of 220 during a documented arrhythmia is signal, not noise. Correct data-entry errors; keep physiologically plausible extremes; consider robust losses (Huber) or robust scalers; and ne"},{"type":"section","title":"10.5 Collection and selection bias","kicker":"Chapter 10 · Missing Values, Outliers, and Collection Bias","url":"read/ch-10.html#s-10-5","text":"Selection bias — the sample differs from the target population (a model trained on a tertiary hospital's sickest patients misestimates risk in primary care). Measurement/collection bias — instruments or practices differ across sites, time, or demographic groups (pulse oximetry overreading SpO₂ in darker skin — a documented, consequential example). Consequences: miscalibration on deployment populat"},{"type":"section","title":"10.6 Key terms","kicker":"Chapter 10 · Missing Values, Outliers, and Collection Bias","url":"read/ch-10.html#s-10-6","text":"MCAR / MAR / MNAR — missingness mechanisms: unrelated / explained by observed data / related to the missing value itself. Imputation — filling missing values with estimates. MICE — multiple imputation by chained equations. Missingness indicator — a binary feature recording that a value was absent. Selection bias — training sample differing from the target population."},{"type":"section","title":"10.7 Review questions","kicker":"Chapter 10 · Missing Values, Outliers, and Collection Bias","url":"read/ch-10.html#s-10-7","text":"Classify: \"a stress test missing because it was contraindicated for this patient.\" Which mechanism, and what does that imply? Why is deleting rows with missing data dangerous in clinical datasets, even under MCAR? Give a clinical example where an outlier must be kept, and one where it must be corrected. How does collection bias become an ethical problem (preview of Unit V)?"},{"type":"chapter","title":"Feature Engineering for EHR Data","kicker":"Unit II · Chapter 11","url":"read/ch-11.html","text":"Construct EHR features from demographics, codes, labs, medications, and utilization. 11.1 Chapter objectives 11.2 Feature families 11.3 Windowing: the core operation 11.4 Leakage traps in EHR work 11.5 Key terms 11.6 Review questions"},{"type":"section","title":"11.1 Chapter objectives","kicker":"Chapter 11 · Feature Engineering for EHR Data","url":"read/ch-11.html#s-11-1","text":"Construct EHR features from demographics, codes, labs, medications, and utilization. Apply windowing and aggregation to build encounter-level design matrices. Recognize the leakage traps specific to EHR data."},{"type":"section","title":"11.2 Feature families","kicker":"Chapter 11 · Feature Engineering for EHR Data","url":"read/ch-11.html#s-11-2","text":"Demographics/administrative: age, sex, encoded race/ethnicity (with fairness care — Unit V), insurance, admission type (elective vs emergency), seasonality. Diagnosis/comorbidity: indicator or count of ICD codes; curated comorbidity indices (Charlson, Elixhauser) that compress diagnoses into validated risk summaries. Labs: latest value, min/max/mean over a window, slope (rate of change), count of "},{"type":"section","title":"11.3 Windowing: the core operation","kicker":"Chapter 11 · Feature Engineering for EHR Data","url":"read/ch-11.html#s-11-3","text":"Clinical prediction is temporal: \"given the first 24 hours, predict the rest of the stay.\" Features are computed over observation windows that end before the prediction time: import pandas as pd # labs: patient_id, timestamp, test, value window = labs[(labs.timestamp < pd.Timestamp(pred_time)) & (labs.timestamp >= pred_time - pd.Timedelta(hours=24))] feat = window.groupby('test')['value'].agg(['la"},{"type":"section","title":"11.4 Leakage traps in EHR work","kicker":"Chapter 11 · Feature Engineering for EHR Data","url":"read/ch-11.html#s-11-4","text":"Look-ahead leakage — using labs drawn because the patient deteriorated (the draw itself is post-decision information). Target leakage — including features that encode the label (a \"sepsis\" diagnosis code that was ordered after the sepsis bundle). Scaling/selection leakage — fitting preprocessors or feature selection on all data. Split leakage — multiple encounters of the same patient in train and "},{"type":"section","title":"11.5 Key terms","kicker":"Chapter 11 · Feature Engineering for EHR Data","url":"read/ch-11.html#s-11-5","text":"Feature engineering — constructing model inputs that encode clinical meaning. Comorbidity index — validated summary of disease burden (Charlson, Elixhauser). Observation window — the time interval whose data is allowed into features. Leakage — any information in training features that would not be available at prediction time. Slope feature — rate of change of a repeated measurement."},{"type":"section","title":"11.6 Review questions","kicker":"Chapter 11 · Feature Engineering for EHR Data","url":"read/ch-11.html#s-11-6","text":"Design six features for a 48-hour readmission model from each data family in §11.2. Why is \"time since last creatinine\" a useful feature even when the value is missing? State two leakage traps unique to EHR data and the split rule that guards against the third."},{"type":"chapter","title":"Physiological Time-Series Features and Dimensionality Reduction","kicker":"Unit II · Chapter 12","url":"read/ch-12.html","text":"Engineer features from vitals and waveforms: window statistics, variability, morphology. 12.1 Chapter objectives 12.2 Time-series feature families 12.3 Feature-based vs sequence models 12.4 Dimensionality reduction 12.5 Key terms 12.6 Review questions"},{"type":"section","title":"12.1 Chapter objectives","kicker":"Chapter 12 · Physiological Time-Series Features and Dimensionality Reduction","url":"read/ch-12.html#s-12-1","text":"Engineer features from vitals and waveforms: window statistics, variability, morphology. Choose between feature-based and sequence-model representations. Apply PCA and feature selection to high-dimensional clinical matrices."},{"type":"section","title":"12.2 Time-series feature families","kicker":"Chapter 12 · Physiological Time-Series Features and Dimensionality Reduction","url":"read/ch-12.html#s-12-2","text":"Window statistics — mean, min, max, std, last value over trailing windows (1 h, 6 h, 24 h). Variability — standard deviation, coefficient of variation; heart-rate variability (HRV) features (RMSSD, SDNN) reflecting autonomic state. Trend — slope (linear fit), delta from baseline, time above/below a clinical threshold. Morphology (waveforms) — ECG intervals (PR, QRS, QT), ST-segment deviation; EEG "},{"type":"section","title":"12.3 Feature-based vs sequence models","kicker":"Chapter 12 · Physiological Time-Series Features and Dimensionality Reduction","url":"read/ch-12.html#s-12-3","text":"Engineered features + gradient-boosted trees remain the strongest default on modest data: interpretable, fast, robust. RNN/LSTM/transformer models consume the raw sequence and learn their own features — better with abundant data and long horizons (Chapter 19). Practical pattern: start feature-based, escalate to sequence models when the feature approach plateaus."},{"type":"section","title":"12.4 Dimensionality reduction","kicker":"Chapter 12 · Physiological Time-Series Features and Dimensionality Reduction","url":"read/ch-12.html#s-12-4","text":"High-dimensional records (thousands of lab features, codes, genomic markers) need reduction: Filtering — remove near-zero-variance and highly correlated features (|r| > 0.95); keep the clinically primary one. Embedded selection — LASSO (L1) regression zeroes out weak features; tree importances (permutation importance, not impurity) rank them. PCA — orthogonal components maximizing variance; useful"},{"type":"section","title":"12.5 Key terms","kicker":"Chapter 12 · Physiological Time-Series Features and Dimensionality Reduction","url":"read/ch-12.html#s-12-5","text":"HRV (heart-rate variability) — beat-to-beat variability features reflecting autonomic tone. Morphology features — shape descriptors of a waveform (intervals, amplitudes, band powers). PCA — linear projection maximizing retained variance. LASSO — L1-regularized regression that performs embedded feature selection. Filter/embedded selection — preprocessing filters vs selection inside model training."},{"type":"section","title":"12.6 Review questions","kicker":"Chapter 12 · Physiological Time-Series Features and Dimensionality Reduction","url":"read/ch-12.html#s-12-6","text":"Derive six time-series features from a 24-hour heart-rate series and state the clinical meaning of two. When would you choose a sequence model over engineered features, and why? Why can PCA hurt a model whose features feed a clinical decision, even if variance retained is high?"},{"type":"chapter","title":"Text Mining and NLP for Clinical Notes","kicker":"Unit II · Chapter 13","url":"read/ch-13.html","text":"Outline the clinical NLP pipeline from raw note to structured feature. 13.1 Chapter objectives 13.2 Why clinical text is hard 13.3 The pipeline 13.4 Downstream uses 13.5 Key terms 13.6 Review questions"},{"type":"section","title":"13.1 Chapter objectives","kicker":"Chapter 13 · Text Mining and NLP for Clinical Notes","url":"read/ch-13.html#s-13-1","text":"Outline the clinical NLP pipeline from raw note to structured feature. Apply the core sub-tasks: section segmentation, negation, entity extraction, coding. Recognize the pitfalls: abbreviations, negation, hedging, and template bloat."},{"type":"section","title":"13.2 Why clinical text is hard","kicker":"Chapter 13 · Text Mining and NLP for Clinical Notes","url":"read/ch-13.html#s-13-2","text":"Notes are written for humans, not parsers: heavy abbreviation (SOB, CAD, NSTEMI), negation (\"no evidence of pneumonia\"), hedging (\"cannot exclude\", \"likely\"), family-history confusion (\"father had MI\"), imprecise dates (\"last week\"), and template/copy-forward bloat. Note that a naive keyword search for \"pneumonia\" matches its own denial."},{"type":"section","title":"13.3 The pipeline","kicker":"Chapter 13 · Text Mining and NLP for Clinical Notes","url":"read/ch-13.html#s-13-3","text":"Preprocessing — section segmentation (History, Meds, Assessment, Plan — assertions differ by section), sentence splitting, abbreviation expansion against a lexicon. Entity extraction (NER) — clinical concept tagging, typically via dictionaries/ontologies ( UMLS , SNOMED CT) or modern transformer models fine-tuned on clinical text (scispaCy, clinical BERT variants). Assertion detection — is the con"},{"type":"section","title":"13.4 Downstream uses","kicker":"Chapter 13 · Text Mining and NLP for Clinical Notes","url":"read/ch-13.html#s-13-4","text":"Auto-coding (ICD assignment from notes — a well-studied NLP benchmark), cohort identification for trials, quality measures, feature engineering (smoking status, symptom flags), report summarization, and patient-facing simplification. Modern LLMs perform extraction and summarization well but need grounding and PHI safeguards (Units III, V)."},{"type":"section","title":"13.5 Key terms","kicker":"Chapter 13 · Text Mining and NLP for Clinical Notes","url":"read/ch-13.html#s-13-5","text":"NER (named entity recognition) — tagging clinical concepts in text. Negation/assertion detection — deciding whether an extracted concept is present, absent, or uncertain. UMLS — the Unified Medical Language System metathesaurus linking clinical vocabularies. Section segmentation — splitting a note into its clinical sections before assertion logic. Auto-coding — assigning ICD/CPT codes from text au"},{"type":"section","title":"13.6 Review questions","kicker":"Chapter 13 · Text Mining and NLP for Clinical Notes","url":"read/ch-13.html#s-13-6","text":"Why is \"no evidence of pneumonia\" the canonical clinical-NLP failure case, and what fixes it? Order the pipeline stages and explain why assertion detection comes after entity extraction. Name two safeguards an LLM-based note summarizer needs before deployment in a hospital (preview Units III, V)."},{"type":"chapter","title":"ICD and CPT Coding Systems","kicker":"Unit II · Chapter 14","url":"read/ch-14.html","text":"Describe the structure and purpose of ICD-10/ICD-10-CM. 14.1 Chapter objectives 14.2 ICD — International Classification of Diseases 14.3 CPT — Current Procedural Terminology 14.4 Integration into healthcare AI 14.5 Related systems (one line each) 14.6 Key terms 14.7 Review questions"},{"type":"section","title":"14.1 Chapter objectives","kicker":"Chapter 14 · ICD and CPT Coding Systems","url":"read/ch-14.html#s-14-1","text":"Describe the structure and purpose of ICD-10/ICD-10-CM. Describe CPT's structure and purpose. Explain how coding systems integrate into healthcare AI, billing, and classification."},{"type":"section","title":"14.2 ICD — International Classification of Diseases","kicker":"Chapter 14 · ICD and CPT Coding Systems","url":"read/ch-14.html#s-14-2","text":"Maintained by the WHO (national clinical modifications like ICD-10-CM are maintained by national bodies, e.g., CMS/CDC in the US; ICD-11 is in adoption). Structure: alphanumeric category codes (three characters) + optional detail (up to 4–7 characters), e.g., E11.9 = Type 2 diabetes mellitus without complications; I21.4 = acute subendocardial myocardial infarction. Purposes: morbidity and mortalit"},{"type":"section","title":"14.3 CPT — Current Procedural Terminology","kicker":"Chapter 14 · ICD and CPT Coding Systems","url":"read/ch-14.html#s-14-3","text":"Maintained by the American Medical Association . Five-character numeric codes describing procedures and services performed by clinicians: 99213 (established-patient office visit), 93306 (echocardiogram), 66984 (routine cataract surgery), grouped into Category I–IV (with Category I the procedures; II performance measures; III emerging tech; IV... actually: I procedures, II performance management, I"},{"type":"section","title":"14.4 Integration into healthcare AI","kicker":"Chapter 14 · ICD and CPT Coding Systems","url":"read/ch-14.html#s-14-4","text":"Labels: ICD codes define cohorts and outcomes (heart-failure readmission = admission with I50.x within 30 days); CPT defines procedures (echo, catheterization) for intervention-adjusted models. Features: code counts and sequences (with caution — coding practice varies by hospital and coder). Auto-coding: NLP maps note text to codes, reducing coder burden and producing consistent labels at scale. B"},{"type":"section","title":"14.5 Related systems (one line each)","kicker":"Chapter 14 · ICD and CPT Coding Systems","url":"read/ch-14.html#s-14-5","text":"SNOMED CT (granular clinical terms), LOINC (lab observations), RxNorm (medications), DRG (payment grouping). ICD answers why treated , CPT answers what was done , SNOMED describes what was found ."},{"type":"section","title":"14.6 Key terms","kicker":"Chapter 14 · ICD and CPT Coding Systems","url":"read/ch-14.html#s-14-6","text":"ICD-10-CM — diagnostic classification; national clinical modification of the WHO standard. CPT — AMA-maintained procedure/service terminology. Auto-coding — NLP-driven assignment of billing/diagnosis codes from clinical text. Code as proxy — using billing codes as labels, with their inherent coding-practice bias."},{"type":"section","title":"14.7 Review questions","kicker":"Chapter 14 · ICD and CPT Coding Systems","url":"read/ch-14.html#s-14-7","text":"Decode E11.9 and 99213 : which system, what does each identify? Give two ML uses of ICD codes and one bias they carry. Why can a model trained on ICD-labeled cohorts misbehave at another hospital? The official question bank for this unit — 18 questions with full model answers — is in Appendix D of this book."},{"type":"chapter","title":"Supervised Learning for Risk Prediction and Diagnostic Classification","kicker":"Unit III · Chapter 15","url":"read/ch-15.html","text":"Frame the two canonical supervised tasks: diagnostic classification and risk prediction. 15.1 Chapter objectives 15.2 The two canonical tasks 15.3 The pipeline, clinically disciplined 15.4 Clinical failure modes 15.5 Key terms 15.6 Review questions"},{"type":"section","title":"15.1 Chapter objectives","kicker":"Chapter 15 · Supervised Learning for Risk Prediction and Diagnostic Classification","url":"read/ch-15.html#s-15-1","text":"Frame the two canonical supervised tasks: diagnostic classification and risk prediction. Build the supervised pipeline with clinical discipline (time-zero, splits, calibration). Recognize healthcare-specific failure modes: leakage, shift, and miscalibration."},{"type":"section","title":"15.2 The two canonical tasks","kicker":"Chapter 15 · Supervised Learning for Risk Prediction and Diagnostic Classification","url":"read/ch-15.html#s-15-2","text":"Diagnostic classification: y = presence of a condition at (or near) prediction time. Binary (disease present/absent) or multiclass (rhythm classification across dozens of arrhythmias). Cross-sectional data: the study at hand plus available history. Risk prediction: y = a future event (readmission within 30 days, deterioration within 12 h, mortality during admission). Longitudinal data; time-zero m"},{"type":"section","title":"15.3 The pipeline, clinically disciplined","kicker":"Chapter 15 · Supervised Learning for Risk Prediction and Diagnostic Classification","url":"read/ch-15.html#s-15-3","text":"cohort definition (inclusion/exclusion, time-zero) → label definition (from ICD/clinical criteria; audit the gold standard) → features (Unit II) over an observation window ending before prediction time → split BY PATIENT (no leakage across train/validation/test) → model (logistic regression / GBM / NN; class weights for imbalance) → evaluation (AUROC, AUPRC, calibration; per-subgroup) → calibratio"},{"type":"section","title":"15.4 Clinical failure modes","kicker":"Chapter 15 · Supervised Learning for Risk Prediction and Diagnostic Classification","url":"read/ch-15.html#s-15-4","text":"Leakage — a lab drawn because the patient deteriorated; a post-decision diagnosis code; a scaler fitted on all data (Chapter 11). Dataset shift — the model meets a different hospital, different coding practice, different population. Miscalibration — an AUROC of 0.85 says nothing about whether \"0.8\" means 80%; calibration curves and Brier scores are mandatory when scores drive decisions. Label nois"},{"type":"section","title":"15.5 Key terms","kicker":"Chapter 15 · Supervised Learning for Risk Prediction and Diagnostic Classification","url":"read/ch-15.html#s-15-5","text":"Risk prediction — supervised prediction of a future clinical event. Diagnostic classification — supervised classification of present condition. Time-zero — the defined moment from which features are measured. Calibration — agreement between predicted probabilities and observed frequencies. Model ladder — logistic regression → GBM → deep nets, in order of data hunger."},{"type":"section","title":"15.6 Review questions","kicker":"Chapter 15 · Supervised Learning for Risk Prediction and Diagnostic Classification","url":"read/ch-15.html#s-15-6","text":"Contrast diagnostic classification and risk prediction on data type and label timing. Why must splits be by patient rather than by encounter? A model has AUROC 0.85 but miscalibrated probabilities. What breaks in deployment?"},{"type":"chapter","title":"Unsupervised Learning: Stratification, Phenotyping, Anomaly Detection","kicker":"Unit III · Chapter 16","url":"read/ch-16.html","text":"Apply clustering to patient stratification and phenotyping. 16.1 Chapter objectives 16.2 Patient stratification and phenotyping 16.3 Anomaly detection 16.4 Key terms 16.5 Review questions"},{"type":"section","title":"16.1 Chapter objectives","kicker":"Chapter 16 · Unsupervised Learning: Stratification, Phenotyping, Anomaly Detection","url":"read/ch-16.html#s-16-1","text":"Apply clustering to patient stratification and phenotyping. Use anomaly detection for clinical outliers and data-quality surveillance. Connect discovered clusters to clinical interpretation and validation."},{"type":"section","title":"16.2 Patient stratification and phenotyping","kicker":"Chapter 16 · Unsupervised Learning: Stratification, Phenotyping, Anomaly Detection","url":"read/ch-16.html#s-16-2","text":"Phenotyping = grouping patients by shared characteristics into clinically meaningful subtypes. Methods: k-means and hierarchical clustering on engineered feature vectors (labs, comorbidities, utilization); Gaussian mixture models for soft assignment; dimensionality reduction (PCA/UMAP) to visualize the structure. Landmark example: clustering of newly diagnosed diabetes patients into five subtypes "},{"type":"section","title":"16.3 Anomaly detection","kicker":"Chapter 16 · Unsupervised Learning: Stratification, Phenotyping, Anomaly Detection","url":"read/ch-16.html#s-16-3","text":"Score how far an observation sits from the learned \"normal\" manifold: isolation forests on tabular EHR windows; one-class SVMs on small clean cohorts; autoencoders whose reconstruction error flags the unusual (Chapter 17's architectures apply). Uses: ICU data-quality surveillance (impossible values, sensor drift), novel-pathogen or unusual-lab-pattern flagging, and fraud in claims. The standing li"},{"type":"section","title":"16.4 Key terms","kicker":"Chapter 16 · Unsupervised Learning: Stratification, Phenotyping, Anomaly Detection","url":"read/ch-16.html#s-16-4","text":"Phenotyping — defining/deriving patient subtypes from data. Stratification — partitioning a population into risk or subtype groups. Isolation forest — tree-based anomaly detector scoring ease of isolation. Autoencoder anomaly score — reconstruction error against a benign-trained manifold. Cluster validation — checking clusters against unused outcomes and clinical actionability."},{"type":"section","title":"16.5 Review questions","kicker":"Chapter 16 · Unsupervised Learning: Stratification, Phenotyping, Anomaly Detection","url":"read/ch-16.html#s-16-5","text":"Describe the diabetes-subtype study as a phenotyping pipeline: features, method, validation. Why is \"anomaly = disease\" the unsupervised rookie error? How would you validate a discovered cluster clinically?"},{"type":"chapter","title":"CNNs and Transfer Learning for Medical Imaging","kicker":"Unit III · Chapter 17","url":"read/ch-17.html","text":"Explain the CNN inductive bias and its fit to medical images. 17.1 Chapter objectives 17.2 Why CNNs fit medical images 17.3 Transfer learning: the small-data solution 17.4 Honest evaluation 17.5 Key terms 17.6 Review questions"},{"type":"section","title":"17.1 Chapter objectives","kicker":"Chapter 17 · CNNs and Transfer Learning for Medical Imaging","url":"read/ch-17.html#s-17-1","text":"Explain the CNN inductive bias and its fit to medical images. Apply transfer learning: what to reuse, when to fine-tune, how much data is needed. Evaluate an imaging model honestly (per-class metrics, external validation)."},{"type":"section","title":"17.2 Why CNNs fit medical images","kicker":"Chapter 17 · CNNs and Transfer Learning for Medical Imaging","url":"read/ch-17.html#s-17-2","text":"A CNN convolves small learned filters across the image, so it encodes two assumptions that are true of radiographs: local patterns matter (edges, textures, lesions) and position matters less than pattern (a nodule can be anywhere). Architectures stack convolutions + pooling into hierarchy: edges → textures → organs → findings. For detection tasks, the same backbone feeds object detectors; for segm"},{"type":"section","title":"17.3 Transfer learning: the small-data solution","kicker":"Chapter 17 · CNNs and Transfer Learning for Medical Imaging","url":"read/ch-17.html#s-17-3","text":"Medical datasets are thousands, not millions; ImageNet pretraining transfers surprisingly well because low-level filters (edges, textures) are universal. The recipe: Pretrained backbone (ResNet, EfficientNet, ViT) — frozen or slowly unfrozen. New head for the clinical task (e.g., 14 CheXpert findings). Fine-tune with a small learning rate; unfreeze progressively if data allows. Augmentation matche"},{"type":"section","title":"17.4 Honest evaluation","kicker":"Chapter 17 · CNNs and Transfer Learning for Medical Imaging","url":"read/ch-17.html#s-17-4","text":"Per-finding AUPRC (imbalanced findings), not accuracy; external validation on a different hospital/scanner population (the single most common gap between papers and products); per-subgroup performance; and clinically meaningful operating points chosen by radiologist review of misses. Interpretability via Grad-CAM/saliency: does the model look at the lesion — or at the pacemaker and the leftmost an"},{"type":"section","title":"17.5 Key terms","kicker":"Chapter 17 · CNNs and Transfer Learning for Medical Imaging","url":"read/ch-17.html#s-17-5","text":"Convolution/pooling — learned local filters / downsampling that builds the feature hierarchy. Transfer learning — reusing pretrained representations for a new task. Fine-tuning — updating pretrained weights (partially/fully) on the clinical task. Grad-CAM — class-activation map showing where the model looked. External validation — evaluation on data from a different population/institution."},{"type":"section","title":"17.6 Review questions","kicker":"Chapter 17 · CNNs and Transfer Learning for Medical Imaging","url":"read/ch-17.html#s-17-6","text":"Why do CNN inductive biases match radiographs, and where do they fail (e.g., counts, laterality with flipped augmentation)? Write the transfer-learning recipe and state when ImageNet pretraining is the wrong source. Why is external validation the most common credibility gap in imaging AI papers?"},{"type":"chapter","title":"RNNs/LSTMs for Clinical Time Series","kicker":"Unit III · Chapter 18","url":"read/ch-18.html","text":"Explain the recurrence and gating mechanics of LSTM/GRU. 18.1 Chapter objectives 18.2 The recurrence and the gates 18.3 Clinical sequence tasks 18.4 Practical notes and the transformer comparison 18.5 Key terms 18.6 Review questions"},{"type":"section","title":"18.1 Chapter objectives","kicker":"Chapter 18 · RNNs/LSTMs for Clinical Time Series","url":"read/ch-18.html#s-18-1","text":"Explain the recurrence and gating mechanics of LSTM/GRU. Build sequence models for vitals/labs: classification and next-step prediction. Choose between recurrent and transformer models on clinical grounds."},{"type":"section","title":"18.2 The recurrence and the gates","kicker":"Chapter 18 · RNNs/LSTMs for Clinical Time Series","url":"read/ch-18.html#s-18-2","text":"A recurrent network processes a sequence one step at a time, carrying a hidden state — but plain RNNs forget (vanishing gradients). The LSTM adds a cell state with gates — forget, input, output — that learn what to keep: f_t = σ(W_f[h_{t-1}, x_t]) # forget: which old context to drop i_t = σ(W_i[h_{t-1}, x_t]) # input: what to write c_t = f_t ⊙ c_{t-1} + i_t ⊙ tanh(W_c[...]) h_t = o_t ⊙ tanh(c_t) #"},{"type":"section","title":"18.3 Clinical sequence tasks","kicker":"Chapter 18 · RNNs/LSTMs for Clinical Time Series","url":"read/ch-18.html#s-18-3","text":"Sequence classification: feed the first-N-hours window (vitals, labs, meds, events) → predict deterioration/sepsis within the next horizon; the model consumes irregular sampling via time-aware encodings (time since last measurement as input). Next-step prediction / anomaly: train on benign trajectories to predict the next value/event; surprise = −log P(observed next step). Unsupervised, useful whe"},{"type":"section","title":"18.4 Practical notes and the transformer comparison","kicker":"Chapter 18 · RNNs/LSTMs for Clinical Time Series","url":"read/ch-18.html#s-18-4","text":"Practicalities dominate: pad/pack sequences for batching; mask and encode irregular sampling; handle missing channels (a vitals stream where SpO₂ appears only when measured); use unidirectional models for online scoring; validate out-of-time (patients from later months in test). Transformers replace recurrence with attention over all positions — better long-range patterns and parallel training; sm"},{"type":"section","title":"18.5 Key terms","kicker":"Chapter 18 · RNNs/LSTMs for Clinical Time Series","url":"read/ch-18.html#s-18-5","text":"Cell state / gates — the LSTM's memory line and its forget/input/output controllers. GRU — two-gate LSTM simplification. Time-aware encoding — representing irregular sampling gaps as model inputs. Next-step surprise — −log P(next event) anomaly scoring on benign-trained sequences. Sequence classification vs next-step prediction — the two deployment patterns."},{"type":"section","title":"18.6 Review questions","kicker":"Chapter 18 · RNNs/LSTMs for Clinical Time Series","url":"read/ch-18.html#s-18-6","text":"Explain what each LSTM gate learns, with a clinical interpretation. Design the input representation for an irregularly sampled vitals+labs sepsis model. Why must the deployment model be unidirectional while a research model could be bidirectional?"},{"type":"chapter","title":"Evaluation Metrics: Sensitivity, Specificity, AUC-ROC, Precision, F1","kicker":"Unit III · Chapter 19","url":"read/ch-19.html","text":"Define the confusion matrix and derive all core metrics from it. 19.1 Chapter objectives 19.2 The confusion matrix and its metrics 19.3 Thresholds, ROC, and PR curves 19.4 Choosing metrics by clinical question 19.5 Key terms 19.6 Review questions"},{"type":"section","title":"19.1 Chapter objectives","kicker":"Chapter 19 · Evaluation Metrics: Sensitivity, Specificity, AUC-ROC, Precision, F1","url":"read/ch-19.html#s-19-1","text":"Define the confusion matrix and derive all core metrics from it. Choose metrics by clinical question and prevalence. Read an ROC and PR curve correctly, including the base-rate trap."},{"type":"section","title":"19.2 The confusion matrix and its metrics","kicker":"Chapter 19 · Evaluation Metrics: Sensitivity, Specificity, AUC-ROC, Precision, F1","url":"read/ch-19.html#s-19-2","text":"Predicted positive Predicted negative Actually positive TP FN Actually negative FP TN Sensitivity (recall, TPR) = TP/(TP+FN) — of the truly diseased, how many did we catch? The metric when missing disease is the dominant cost (screening). Specificity (TNR) = TN/(TN+FP) — of the truly healthy, how many were correctly cleared? Precision (PPV) = TP/(TP+FP) — of those we flagged, how many were real? T"},{"type":"section","title":"19.3 Thresholds, ROC, and PR curves","kicker":"Chapter 19 · Evaluation Metrics: Sensitivity, Specificity, AUC-ROC, Precision, F1","url":"read/ch-19.html#s-19-3","text":"Metrics above depend on a threshold; curves characterize the whole range . ROC plots TPR vs FPR (1−specificity) across thresholds; AUC-ROC = probability a random positive ranks above a random negative. PR curves plot precision vs recall; AUPRC is far more informative at low prevalence — the base-rate trap: with 0.1% positives, an ROC-AUC of 0.999 can still mean unacceptable precision. Diagnostic r"},{"type":"section","title":"19.4 Choosing metrics by clinical question","kicker":"Chapter 19 · Evaluation Metrics: Sensitivity, Specificity, AUC-ROC, Precision, F1","url":"read/ch-19.html#s-19-4","text":"Clinical question Metric Screening: don't miss disease Sensitivity (at an acceptable specificity floor) Avoid unnecessary invasive follow-up Precision/PPV Rule out safely Specificity / NPV Rank patients for review AUC-ROC, AUPRC Automated action on the score Calibration (Brier), per-subgroup Also report the confusion matrix at the clinically chosen operating point , calibration plots, and per-subg"},{"type":"section","title":"19.5 Key terms","kicker":"Chapter 19 · Evaluation Metrics: Sensitivity, Specificity, AUC-ROC, Precision, F1","url":"read/ch-19.html#s-19-5","text":"Sensitivity / Specificity — TPR / TNR. PPV / NPV — predictive values; prevalence-dependent. AUC-ROC / AUPRC — area under ROC / precision-recall curves. Base-rate trap — ROC-AUC flattering a model at low prevalence. Operating point — the threshold chosen for deployment by clinical cost."},{"type":"section","title":"19.6 Review questions","kicker":"Chapter 19 · Evaluation Metrics: Sensitivity, Specificity, AUC-ROC, Precision, F1","url":"read/ch-19.html#s-19-6","text":"Derive sensitivity, specificity, PPV, NPV from a 2×2 table with worked numbers. Why is AUPRC the better default for rare-disease screening? Two models have equal AUROC; one has far better calibration. Which deploys, and why?"},{"type":"chapter","title":"Imbalanced Healthcare Datasets: Rare Disease Detection","kicker":"Unit III · Chapter 20","url":"read/ch-20.html","text":"Quantify the imbalance problem and its effect on training and metrics. 20.1 Chapter objectives 20.2 The problem, quantified 20.3 The toolbox 20.4 Evaluation that survives imbalance 20.5 Key terms 20.6 Review questions"},{"type":"section","title":"20.1 Chapter objectives","kicker":"Chapter 20 · Imbalanced Healthcare Datasets: Rare Disease Detection","url":"read/ch-20.html#s-20-1","text":"Quantify the imbalance problem and its effect on training and metrics. Apply resampling, cost-sensitive learning, and threshold methods. Design evaluation that survives imbalance (PR curves, per-subgroup, calibration)."},{"type":"section","title":"20.2 The problem, quantified","kicker":"Chapter 20 · Imbalanced Healthcare Datasets: Rare Disease Detection","url":"read/ch-20.html#s-20-2","text":"Rare diseases run 1:1,000 to 1:100,000. Consequences: accuracy is meaningless (\"all negative\" = 99.9%); loss functions are dominated by negatives (a model that predicts nothing is \"optimal\" under plain MSE/CE); validation sets hold a handful of positives; and calibration at the decision boundary is built on almost no signal."},{"type":"section","title":"20.3 The toolbox","kicker":"Chapter 20 · Imbalanced Healthcare Datasets: Rare Disease Detection","url":"read/ch-20.html#s-20-3","text":"Data-level: undersample the majority; oversample the minority; SMOTE (synthetic minority interpolation — with the caveat that interpolated patients may be clinically implausible; prefer real data); targeted data collection (registries, multi-site pooling). Cost-level: class weights ( pos_weight ≈ N_neg/N_pos ), focal loss ((1−p_t)^γ focuses training on hard cases), and threshold selection by clini"},{"type":"section","title":"20.4 Evaluation that survives imbalance","kicker":"Chapter 20 · Imbalanced Healthcare Datasets: Rare Disease Detection","url":"read/ch-20.html#s-20-4","text":"Report AUPRC and precision at k (the analyst's/clinician's attention budget); the confusion matrix at the clinical operating point; per-subgroup sensitivity/specificity (imbalance often correlates with demographics — Unit V); and calibration. Beware the ROC trap (Chapter 19). For rare diseases specifically, state the absolute numbers (e.g., \"1 of 3 true positives caught at 500 false positives per "},{"type":"section","title":"20.5 Key terms","kicker":"Chapter 20 · Imbalanced Healthcare Datasets: Rare Disease Detection","url":"read/ch-20.html#s-20-5","text":"Class imbalance — positive prevalence far below 50%. SMOTE — synthetic minority oversampling by interpolation. Focal loss — down-weights easy examples, focuses on hard ones. Threshold by cost — operating point chosen from the clinic's FP/FN cost structure. Small-denominator fragility — metrics on few positives have huge uncertainty."},{"type":"section","title":"20.6 Review questions","kicker":"Chapter 20 · Imbalanced Healthcare Datasets: Rare Disease Detection","url":"read/ch-20.html#s-20-6","text":"Show numerically why accuracy fails at 1:1,000 prevalence. When is SMOTE harmful in clinical data? Design the evaluation report for a 1:10,000 screening model (list every component)."},{"type":"chapter","title":"Explainable AI: LIME and SHAP","kicker":"Unit III · Chapter 21","url":"read/ch-21.html","text":"Explain LIME's local-surrogate mechanism and its guarantees/limits. 21.1 Chapter objectives 21.2 LIME — Local Interpretable Model-agnostic Explanations 21.3 SHAP — SHapley Additive exPlanations 21.4 The clinical explanation artifact 21.5 Key terms 21.7 Review questions"},{"type":"section","title":"21.1 Chapter objectives","kicker":"Chapter 21 · Explainable AI: LIME and SHAP","url":"read/ch-21.html#s-21-1","text":"Explain LIME's local-surrogate mechanism and its guarantees/limits. Explain SHAP's Shapley-value attribution and its properties. Design the explanation artifact a clinical alert should carry."},{"type":"section","title":"21.2 LIME — Local Interpretable Model-agnostic Explanations","kicker":"Chapter 21 · Explainable AI: LIME and SHAP","url":"read/ch-21.html#s-21-2","text":"Idea: approximate the black box locally with a simple interpretable model (linear/decision-tree). Procedure: (1) take the instance; (2) perturb it — generate nearby samples (flip features, perturb pixels); (3) get the black box's predictions on the perturbed set; (4) weight samples by proximity; (5) fit a sparse linear model on the weighted samples; its coefficients are the local explanation. Stre"},{"type":"section","title":"21.3 SHAP — SHapley Additive exPlanations","kicker":"Chapter 21 · Explainable AI: LIME and SHAP","url":"read/ch-21.html#s-21-3","text":"Idea: from cooperative game theory — the Shapley value of a feature is its average marginal contribution to the prediction across all coalitions of features. SHAP computes/add-approximates these values so that f(x) = base + Σ φ_i (additivity). Properties: local accuracy (explanations add up to the prediction), consistency (if a model depends more on a feature, its attribution doesn't decrease), an"},{"type":"section","title":"21.4 The clinical explanation artifact","kicker":"Chapter 21 · Explainable AI: LIME and SHAP","url":"read/ch-21.html#s-21-4","text":"A usable alert carries: the calibrated score + confidence band ; top-3 pushers and top-1 suppressor with attribution values in plain clinical language ; similar past cases and their outcomes; a counterfactual (\"had HbA1c been < 6.5, score would drop to 0.2\"); and the model's stated limitations. LIME/SHAP supply the attributions; the artifact supplies the framing — attribution shows which feature p"},{"type":"section","title":"21.5 Key terms","kicker":"Chapter 21 · Explainable AI: LIME and SHAP","url":"read/ch-21.html#s-21-5","text":"LIME — local surrogate explanation by perturbation. SHAP / Shapley value — game-theoretic average marginal contribution per feature. Local accuracy / additivity — SHAP values sum to the prediction. TreeSHAP — exact fast SHAP for tree ensembles. Attribution ≠ causation — the standing caveat on all post-hoc explanation."},{"type":"section","title":"21.7 Review questions","kicker":"Chapter 21 · Explainable AI: LIME and SHAP","url":"read/ch-21.html#s-21-7","text":"Write LIME's five-step procedure and name its two stability limits. State SHAP's additivity property and what TreeSHAP changes practically. Compose the seven-field explanation artifact for a sepsis alert."},{"type":"chapter","title":"Privacy, Anonymization, and HIPAA","kicker":"Unit III · Chapter 22","url":"read/ch-22.html","text":"State what HIPAA regulates: PHI, Privacy Rule, Security Rule, BAAs. 22.1 Chapter objectives 22.2 What HIPAA regulates 22.3 De-identification 22.4 A compliant ML pipeline 22.5 Key terms 22.6 Review questions"},{"type":"section","title":"22.1 Chapter objectives","kicker":"Chapter 22 · Privacy, Anonymization, and HIPAA","url":"read/ch-22.html#s-22-1","text":"State what HIPAA regulates: PHI, Privacy Rule, Security Rule, BAAs. Apply the two de-identification standards (Safe Harbor, Expert Determination). Design a compliant ML pipeline from ingestion to deployment."},{"type":"section","title":"22.2 What HIPAA regulates","kicker":"Chapter 22 · Privacy, Anonymization, and HIPAA","url":"read/ch-22.html#s-22-2","text":"PHI (Protected Health Information): health data tied to an identifier. Privacy Rule: who may use/disclose PHI; minimum necessary principle; patient rights (access, amendment, accounting). Security Rule: administrative/physical/technical safeguards for electronic PHI (access control, audit trails, encryption). Business Associate Agreement (BAA): required contract with any vendor processing PHI — a "},{"type":"section","title":"22.3 De-identification","kicker":"Chapter 22 · Privacy, Anonymization, and HIPAA","url":"read/ch-22.html#s-22-3","text":"Safe Harbor: remove all 18 identifier categories — names; geography finer than state; all date elements (except year) tied to the patient; ages > 89 aggregated; contact details; SSN/MRN/insurance/account/license/vehicle/device/URL/IP; biometrics; full-face photos; any other unique identifier — and no actual knowledge that re-identification is possible. Expert Determination: a qualified statisticia"},{"type":"section","title":"22.4 A compliant ML pipeline","kicker":"Chapter 22 · Privacy, Anonymization, and HIPAA","url":"read/ch-22.html#s-22-4","text":"Ingestion: minimal necessary data only; pseudonymized keys (salted hash; key held separately); date-shifting per patient (preserve intervals). Text: PHI scrubbing via NLP before any note leaves the clinical environment. Access: role-based, logged; training environments separated from production EHR. Training: on de-identified/pseudonymized data; consider federated learning when data cannot move (U"},{"type":"section","title":"22.5 Key terms","kicker":"Chapter 22 · Privacy, Anonymization, and HIPAA","url":"read/ch-22.html#s-22-5","text":"PHI — protected health information; health data linked to identifiers. Privacy / Security Rule — use-disclosure governance / technical safeguards. BAA — Business Associate Agreement with PHI-processing vendors. Safe Harbor / Expert Determination — HIPAA's two de-identification standards. Date-shifting / pseudonymization — utility-preserving de-identification techniques."},{"type":"section","title":"22.6 Review questions","kicker":"Chapter 22 · Privacy, Anonymization, and HIPAA","url":"read/ch-22.html#s-22-6","text":"List any six of HIPAA's 18 Safe Harbor identifier categories. Why is a cloud ML provider a \"legal relationship\" and what document governs it? Design the de-identification steps for a notes+labs dataset destined for a shared training cluster. The official question bank for this unit — 18 questions with full model answers — is in Appendix D of this book."},{"type":"chapter","title":"AI in Disease Diagnosis: Diabetes, Cancer, Heart Disease","kicker":"Unit IV · Chapter 23","url":"read/ch-23.html","text":"Describe AI diagnostic workflows for diabetes, cancer, and heart disease. 23.1 Chapter objectives 23.2 Diabetes — the autonomous screening template 23.3 Cancer — screening, grading, and planning 23.4 Heart disease — waveform interpretation at scale 23.5 The transferable design pattern 23.6 Key terms 23.7 Review questions"},{"type":"section","title":"23.1 Chapter objectives","kicker":"Chapter 23 · AI in Disease Diagnosis: Diabetes, Cancer, Heart Disease","url":"read/ch-23.html#s-23-1","text":"Describe AI diagnostic workflows for diabetes, cancer, and heart disease. Connect each workflow to its imaging/lab substrate and its regulatory story. Extract the transferable design pattern: screening-grade vs diagnostic-grade claims."},{"type":"section","title":"23.2 Diabetes — the autonomous screening template","kicker":"Chapter 23 · AI in Disease Diagnosis: Diabetes, Cancer, Heart Disease","url":"read/ch-23.html#s-23-2","text":"Diabetes contributes AI on three fronts: retinopathy screening (the landmark: IDx-DR, FDA-authorized 2018 — a CNN reading retinal photographs for more-than-mild diabetic retinopathy, autonomous when confident, with predefined \"re-image/refer\" fallbacks); nephropathy and foot-risk prediction from EHR trajectories; and glucose forecasting from CGM streams for closed-loop insulin. Lesson: the autonom"},{"type":"section","title":"23.3 Cancer — screening, grading, and planning","kicker":"Chapter 23 · AI in Disease Diagnosis: Diabetes, Cancer, Heart Disease","url":"read/ch-23.html#s-23-3","text":"Cancer AI spans the full pipeline: screening (mammography support — large trials showing AI-supported reading matches double reading with reduced workload; lung CT nodule detection for high-risk screening), detection and grading (dermoscopy classification; whole-slide pathology for lymph-node metastasis and Gleason grading), prognosis (survival models fusing tumor features, genomics, treatment), a"},{"type":"section","title":"23.4 Heart disease — waveform interpretation at scale","kicker":"Chapter 23 · AI in Disease Diagnosis: Diabetes, Cancer, Heart Disease","url":"read/ch-23.html#s-23-4","text":"ECG deep models classify dozens of rhythms at cardiologist level; AI estimates ejection fraction from echocardiography ; coronary calcium scoring from CT is fully automated; wearables screen for AF from single-lead PPG (Apple Heart Study: pragmatic at-scale validation). Lesson: cardiologists already work at machine-comparable granularity on 1-D signals, so AI's gain here is throughput and continuo"},{"type":"section","title":"23.5 The transferable design pattern","kicker":"Chapter 23 · AI in Disease Diagnosis: Diabetes, Cancer, Heart Disease","url":"read/ch-23.html#s-23-5","text":"Screening-grade vs diagnostic-grade. A screening model must be maximally sensitive at acceptable specificity (misses are catastrophic; false positives cost confirmatory tests). A diagnostic-grade claim (\"this is a fracture\") requires much higher precision and usually expert confirmation. Most deployed systems are screening/triage-grade; the regulatory pathway (Unit V) matches the claim."},{"type":"section","title":"23.6 Key terms","kicker":"Chapter 23 · AI in Disease Diagnosis: Diabetes, Cancer, Heart Disease","url":"read/ch-23.html#s-23-6","text":"IDx-DR — first FDA-authorized autonomous diagnostic AI (diabetic retinopathy, 2018). More-than-mild DR — the screening threshold used by retinopathy programs. Radiotherapy auto-contouring — AI delineation of tumors/organs at risk. Screening-grade claim — high-sensitivity triage claim, confirmatory test to follow."},{"type":"section","title":"23.7 Review questions","kicker":"Chapter 23 · AI in Disease Diagnosis: Diabetes, Cancer, Heart Disease","url":"read/ch-23.html#s-23-7","text":"Why was retinopathy the right first disease for an autonomous AI diagnostic? Contrast screening-grade and diagnostic-grade claims with the metric each optimizes. What intermediate endpoint does mammography AI use, and why?"},{"type":"chapter","title":"Multi-Modal AI Systems","kicker":"Unit IV · Chapter 24","url":"read/ch-24.html","text":"Define multi-modal fusion and its architectural patterns (early/late/attention). 24.1 Chapter objectives 24.2 Fusion patterns 24.3 A concrete fused pipeline 24.4 Failure modes 24.5 Key terms 24.6 Review questions"},{"type":"section","title":"24.1 Chapter objectives","kicker":"Chapter 24 · Multi-Modal AI Systems","url":"read/ch-24.html#s-24-1","text":"Define multi-modal fusion and its architectural patterns (early/late/attention). Trace a concrete fused pipeline (imaging + labs + notes). Recognize multi-modal failure modes: missing modalities and shortcut fusion."},{"type":"section","title":"24.2 Fusion patterns","kicker":"Chapter 24 · Multi-Modal AI Systems","url":"read/ch-24.html#s-24-2","text":"Early fusion: concatenate feature vectors from each modality before the model. Simple; assumes comparable scales; loses modality-specific structure. Late fusion: one model per modality, combine their outputs (weighted average, stacking). Robust to a missing modality (each still predicts); misses cross-modal interactions. Cross-modal attention (modern): shared latent space; attention layers let eac"},{"type":"section","title":"24.3 A concrete fused pipeline","kicker":"Chapter 24 · Multi-Modal AI Systems","url":"read/ch-24.html#s-24-3","text":"ICU deterioration: an imaging/history encoder (EHR features from Unit II), a lab-trajectory model (LSTM, Chapter 18), a chest-X-ray CNN (Chapter 17), and a note encoder (clinical BERT, Chapter 13) — outputs fused by late stacking into one calibrated score. The clinical insight multi-modal fusion captures: the X-ray was abnormal but subtle, and the trajectory confirms it — neither alone is as speci"},{"type":"section","title":"24.4 Failure modes","kicker":"Chapter 24 · Multi-Modal AI Systems","url":"read/ch-24.html#s-24-4","text":"Missing modality at inference — the scan wasn't done today; late fusion degrades gracefully, early fusion breaks; design for graceful degradation. Shortcut fusion — the fusion layer leans on the easiest modality (a note saying \"sepsis bundle started\" leaks the label); audit per-modality contributions. Synchronization — modalities describe different times; define the prediction-time alignment expli"},{"type":"section","title":"24.5 Key terms","kicker":"Chapter 24 · Multi-Modal AI Systems","url":"read/ch-24.html#s-24-5","text":"Early / late fusion — concatenating features / combining per-modality outputs. Cross-modal attention — attention across modality-specific representations. Graceful degradation — continued usable prediction when a modality is missing. Shortcut fusion — a fused model dominated by one leak-prone modality."},{"type":"section","title":"24.6 Review questions","kicker":"Chapter 24 · Multi-Modal AI Systems","url":"read/ch-24.html#s-24-6","text":"Contrast early and late fusion on missing-modality robustness. Why can a note encoder turn a multi-modal model into a leakage machine? Design the prediction-time alignment rule for a three-modality ICU model."},{"type":"chapter","title":"Advanced Medical Image Analysis: Detection and Segmentation","kicker":"Unit IV · Chapter 25","url":"read/ch-25.html","text":"Distinguish classification, detection, and segmentation tasks and their metrics. 25.1 Chapter objectives 25.2 The task ladder 25.3 U-Net — the segmentation workhorse 25.4 Deployed segmentation applications 25.5 Key terms 25.6 Review questions"},{"type":"section","title":"25.1 Chapter objectives","kicker":"Chapter 25 · Advanced Medical Image Analysis: Detection and Segmentation","url":"read/ch-25.html#s-25-1","text":"Distinguish classification, detection, and segmentation tasks and their metrics. Explain the U-Net architecture and the Dice metric. Describe deployed segmentation applications and their human-verification loops."},{"type":"section","title":"25.2 The task ladder","kicker":"Chapter 25 · Advanced Medical Image Analysis: Detection and Segmentation","url":"read/ch-25.html#s-25-2","text":"Task Question Output Metric Classification Is the finding present? Label per image/study AUC, AUPRC, sensitivity/specificity Detection Where is it? Bounding boxes / candidates Sensitivity per lesion, FROC Segmentation What are its exact outlines? Pixel/voxel masks Dice , IoU, Hausdorff distance"},{"type":"section","title":"25.3 U-Net — the segmentation workhorse","kicker":"Chapter 25 · Advanced Medical Image Analysis: Detection and Segmentation","url":"read/ch-25.html#s-25-3","text":"An encoder–decoder: the encoder downsamples to a semantic bottleneck; the decoder upsamples back to full resolution; skip connections carry early high-resolution detail across, so boundaries stay sharp. Losses: Dice loss / combined Dice+cross-entropy (robust to tiny structures in huge images). Variants: 3-D convolutions for CT/MRI volumes; nnU-Net (self-configuring U-Net) is the practical default "},{"type":"section","title":"25.4 Deployed segmentation applications","kicker":"Chapter 25 · Advanced Medical Image Analysis: Detection and Segmentation","url":"read/ch-25.html#s-25-4","text":"Radiotherapy planning: auto-contouring of tumors and organs at risk (heart, spinal cord, parotids) — reduces hours of manual contouring to minutes, with radiation-oncologist verification mandatory. Volumetry: tumor and organ volumes over time (response assessment). Surgical guidance: real-time segmentation in endoscopic video. Stroke: infarct-core segmentation to speed thrombectomy decisions. Reti"},{"type":"section","title":"25.5 Key terms","kicker":"Chapter 25 · Advanced Medical Image Analysis: Detection and Segmentation","url":"read/ch-25.html#s-25-5","text":"Segmentation — pixel/voxel-level delineation of a structure. U-Net / skip connections — encoder-decoder with cross-scale detail paths. Dice coefficient — overlap metric: 2|A∩B|/(|A|+|B|). FROC — free-response ROC for detection tasks. nnU-Net — self-configuring segmentation pipeline; the practical default."},{"type":"section","title":"25.6 Review questions","kicker":"Chapter 25 · Advanced Medical Image Analysis: Detection and Segmentation","url":"read/ch-25.html#s-25-6","text":"Match each task type (classification/detection/segmentation) to a clinical use and metric. Why do skip connections matter for medical segmentation specifically? What makes Dice the right loss for small lesions, and when does it mislead?"},{"type":"chapter","title":"Predictive Analytics in Critical Care (ICU)","kicker":"Unit IV · Chapter 26","url":"read/ch-26.html","text":"Frame the three ICU prediction tasks: deterioration, length of stay, mortality. 26.1 Chapter objectives 26.2 The three tasks 26.3 Scores vs learned models 26.4 Benchmark datasets and their discipline 26.5 Key terms 26.6 Review questions"},{"type":"section","title":"26.1 Chapter objectives","kicker":"Chapter 26 · Predictive Analytics in Critical Care (ICU)","url":"read/ch-26.html#s-26-1","text":"Frame the three ICU prediction tasks: deterioration, length of stay, mortality. Compare classical scores (NEWS/APACHE/SAPS) with learned models. Work with the benchmark datasets (MIMIC) and their discipline."},{"type":"section","title":"26.2 The three tasks","kicker":"Chapter 26 · Predictive Analytics in Critical Care (ICU)","url":"read/ch-26.html#s-26-2","text":"Deterioration/early warning: predict decompensation or sepsis hours ahead from vitals+labs trajectories (Chapters 18–19 architectures). Value = time for intervention; cost = alarm burden. Length of stay (LOS): forecast remaining stay for capacity planning and discharge targeting; skewed long-tail target — model log-LOS or quantiles, not raw means. Mortality risk: classical severity scores ( APACHE"},{"type":"section","title":"26.3 Scores vs learned models","kicker":"Chapter 26 · Predictive Analytics in Critical Care (ICU)","url":"read/ch-26.html#s-26-3","text":"Dimension Classical scores Learned models Features Fixed handful, measured once Full trajectory, all streams Calibration Established across sites Must be validated locally Transparency Fully transparent Needs XAI artifacts Adaptation Static Retrainable; drift-monitored The mature pattern: scores remain the floor (transparent, ubiquitous); learned models layer on top where their added discriminatio"},{"type":"section","title":"26.4 Benchmark datasets and their discipline","kicker":"Chapter 26 · Predictive Analytics in Critical Care (ICU)","url":"read/ch-26.html#s-26-4","text":"MIMIC-III/IV (MIT-hosted critical-care EHR dataset, de-identified, credentialed access) and eICU power most ICU-ML research. Discipline: define time-zero identically; exclude post-death artifacts (labs drawn after death leak); split by patient; report calibration; and remember MIMIC is two hospitals from one decade — external validity claims must be correspondingly modest."},{"type":"section","title":"26.5 Key terms","kicker":"Chapter 26 · Predictive Analytics in Critical Care (ICU)","url":"read/ch-26.html#s-26-5","text":"NEWS / APACHE / SAPS — classical early-warning and severity scores. Deterioration horizon — how many hours ahead the model warns. MIMIC-III/IV — de-identified critical-care benchmark datasets. Post-death artifact leakage — data generated by the dying process leaking into features."},{"type":"section","title":"26.6 Review questions","kicker":"Chapter 26 · Predictive Analytics in Critical Care (ICU)","url":"read/ch-26.html#s-26-6","text":"Contrast NEWS and a learned sepsis model on transparency and discrimination. Why is raw LOS a bad regression target? What is post-death artifact leakage and how is it excluded?"},{"type":"chapter","title":"Genomics, Pharmacogenomics, and Personalized Medicine","kicker":"Unit IV · Chapter 27","url":"read/ch-27.html","text":"Describe the sequencing-to-variant pipeline and where ML enters it. 27.1 Chapter objectives 27.2 The pipeline and ML's entries 27.3 Polygenic risk scores and pharmacogenomics 27.4 Precision oncology 27.5 Key terms 27.6 Review questions"},{"type":"section","title":"27.1 Chapter objectives","kicker":"Chapter 27 · Genomics, Pharmacogenomics, and Personalized Medicine","url":"read/ch-27.html#s-27-1","text":"Describe the sequencing-to-variant pipeline and where ML enters it. Explain polygenic risk scores and pharmacogenomics. Connect precision oncology to multi-modal clinical AI."},{"type":"section","title":"27.2 The pipeline and ML's entries","kicker":"Chapter 27 · Genomics, Pharmacogenomics, and Personalized Medicine","url":"read/ch-27.html#s-27-2","text":"Sequencing produces FASTQ (reads) → alignment ( BAM ) → variant calling ( VCF ). ML enters at: variant calling (deep-learning callers rival classical GATK on indels), variant interpretation — classifying a variant as pathogenic/benign from conservation, predicted protein effects, and population frequency (AlphaMissense-style classifiers), gene expression/omics (tumor vs normal expression signature"},{"type":"section","title":"27.3 Polygenic risk scores and pharmacogenomics","kicker":"Chapter 27 · Genomics, Pharmacogenomics, and Personalized Medicine","url":"read/ch-27.html#s-27-3","text":"Polygenic risk scores (PRS): aggregate millions of common variants (weights from genome-wide association studies) into a risk number for common diseases (CAD, breast cancer). Use: risk stratification to target screening. Limits: ancestry transferability — PRS built in European cohorts lose calibration in other populations (an equity problem, Unit V). Pharmacogenomics: inherited metabolism variants"},{"type":"section","title":"27.4 Precision oncology","kicker":"Chapter 27 · Genomics, Pharmacogenomics, and Personalized Medicine","url":"read/ch-27.html#s-27-4","text":"Tumor–normal sequencing identifies somatic drivers; clinical decision support matches drivers to targeted therapies and trials (EGFR → EGFR inhibitors; BRAF V600E → BRAF inhibitors; MSI-high → immunotherapy). AI contributions: variant prioritization, biomarker extraction from pathology slides (predicting mutations from H&E morphology — \"genotype from the glass\"), and trial matching. This is multi-"},{"type":"section","title":"27.5 Key terms","kicker":"Chapter 27 · Genomics, Pharmacogenomics, and Personalized Medicine","url":"read/ch-27.html#s-27-5","text":"FASTQ/BAM/VCF — reads / alignments / variant calls. Pathogenicity classification — ML-based benign-vs-pathogenic variant prediction. Polygenic risk score (PRS) — weighted aggregate of common-variant risk. Pharmacogenomics — genotype-guided drug selection and dosing. Precision oncology — therapy matched to the tumor's molecular profile."},{"type":"section","title":"27.6 Review questions","kicker":"Chapter 27 · Genomics, Pharmacogenomics, and Personalized Medicine","url":"read/ch-27.html#s-27-6","text":"Name the three file formats of the sequencing pipeline and one ML task at each stage. Why do PRSs raise an equity concern, and what is the mitigation? Give one example of genotype-guided dosing and one of genotype-guided drug avoidance."},{"type":"chapter","title":"AI-Driven Drug Discovery and Repurposing","kicker":"Unit IV · Chapter 28","url":"read/ch-28.html","text":"Map the drug-discovery pipeline and AI's entry points. 28.1 Chapter objectives 28.2 The pipeline and AI's entries 28.3 Drug repurposing 28.4 Honest assessment 28.5 Key terms 28.6 Review questions"},{"type":"section","title":"28.1 Chapter objectives","kicker":"Chapter 28 · AI-Driven Drug Discovery and Repurposing","url":"read/ch-28.html#s-28-1","text":"Map the drug-discovery pipeline and AI's entry points. Describe generative molecule design and property prediction. Explain drug repurposing with real examples."},{"type":"section","title":"28.2 The pipeline and AI's entries","kicker":"Chapter 28 · AI-Driven Drug Discovery and Repurposing","url":"read/ch-28.html#s-28-2","text":"The classical pipeline — target identification → hit discovery → lead optimization → preclinical → clinical trials (I–III) → approval — takes 10–15 years and >$1–2B, dominated by clinical-trial failure. AI's leverage points: Target identification — mining omics data, literature, and pathways to nominate disease-relevant targets (network/graph ML on protein–protein interactions). Hit discovery / vi"},{"type":"section","title":"28.3 Drug repurposing","kicker":"Chapter 28 · AI-Driven Drug Discovery and Repurposing","url":"read/ch-28.html#s-28-3","text":"Finding new uses for approved drugs — the fastest path to patients because safety profiles already exist. AI approaches: signature matching (does a drug's gene-expression signature reverse the disease signature?), knowledge-graph reasoning over drugs/diseases/targets, and literature mining. Real examples: baricitinib (a rheumatoid-arthritis JAK inhibitor nominated for COVID-19 by an AI knowledge-g"},{"type":"section","title":"28.4 Honest assessment","kicker":"Chapter 28 · AI-Driven Drug Discovery and Repurposing","url":"read/ch-28.html#s-28-4","text":"AI-computed candidates still fail in wet-lab and clinical validation; the gains are in narrowing search (fewer, better candidates entering expensive stages), not in skipping validation. Claims of \"AI-designed drugs\" are pipeline claims — the design step accelerated, the rest unchanged."},{"type":"section","title":"28.5 Key terms","kicker":"Chapter 28 · AI-Driven Drug Discovery and Repurposing","url":"read/ch-28.html#s-28-5","text":"Virtual screening — ML-predicted prioritization of compound libraries. QSAR — quantitative structure–activity relationship; property prediction from structure. Generative molecule design — models proposing novel structures. Signature reversal — matching drug signatures against disease signatures for repurposing. Knowledge-graph drug repurposing — reasoning over drug/target/disease graphs."},{"type":"section","title":"28.6 Review questions","kicker":"Chapter 28 · AI-Driven Drug Discovery and Repurposing","url":"read/ch-28.html#s-28-6","text":"At which two pipeline stages does AI save the most time, and why? Explain signature-reversal repurposing in three sentences. Why is baricitinib's story the honest template for \"AI-discovered\" claims?"},{"type":"chapter","title":"Digital Health: Chatbots, Virtual Assistants, IoT, and Wearables","kicker":"Unit IV · Chapter 29","url":"read/ch-29.html","text":"Define virtual health assistants and their safe scope of use. 29.1 Chapter objectives 29.2 Virtual health assistants and chatbots 29.3 IoT medical devices and AI 29.4 Wearables and the AF-detection template 29.5 Key terms 29.6 Review questions"},{"type":"section","title":"29.1 Chapter objectives","kicker":"Chapter 29 · Digital Health: Chatbots, Virtual Assistants, IoT, and Wearables","url":"read/ch-29.html#s-29-1","text":"Define virtual health assistants and their safe scope of use. Describe IoT medical-device architecture and its AI roles. Evaluate wearable monitoring claims (AF detection as the template)."},{"type":"section","title":"29.2 Virtual health assistants and chatbots","kicker":"Chapter 29 · Digital Health: Chatbots, Virtual Assistants, IoT, and Wearables","url":"read/ch-29.html#s-29-2","text":"Conversational agents for: symptom triage and routing (\"is this an ER problem?\"), medication reminders and adherence support, chronic-disease coaching (diabetes, hypertension), post-discharge check-ins, and administrative help (scheduling, refill requests). Design constraints: they are triage and support tools, not diagnosticians — escalation logic (\"if red flag → seek care now\") is rule-based and"},{"type":"section","title":"29.3 IoT medical devices and AI","kicker":"Chapter 29 · Digital Health: Chatbots, Virtual Assistants, IoT, and Wearables","url":"read/ch-29.html#s-29-3","text":"Architecture: sensors (continuous glucose monitors, SpO₂, BP cuffs, scales) → gateway/hub or phone → cloud platform → ML services → clinician dashboard / alerts. AI roles: signal cleaning and artifact rejection, event detection (arrhythmia, hypoglycemia forecasting), adherence inference, and predictive maintenance of devices themselves. Constraints: connectivity outages (edge models must degrade g"},{"type":"section","title":"29.4 Wearables and the AF-detection template","kicker":"Chapter 29 · Digital Health: Chatbots, Virtual Assistants, IoT, and Wearables","url":"read/ch-29.html#s-29-4","text":"Consumer wearables run PPG-based arrhythmia screening at population scale: the device flags irregular pulses; an ECG patch confirms; large pragmatic studies (Apple Heart Study) validated the pipeline's positive predictive value (~0.84) and the operational lesson: screening claims live or die on what happens after the flag . Design lessons: conservative flags, clear confirmatory pathway, honest com"},{"type":"section","title":"29.5 Key terms","kicker":"Chapter 29 · Digital Health: Chatbots, Virtual Assistants, IoT, and Wearables","url":"read/ch-29.html#s-29-5","text":"Virtual health assistant — conversational agent for triage/coaching/administrative support. RPM — remote patient monitoring built on IoT streams. CGM — continuous glucose monitoring. PPG — photoplethysmography; the optical pulse signal behind wearable HR/AF detection. Escalation rule — the conservative red-flag logic in triage chatbots."},{"type":"section","title":"29.6 Review questions","kicker":"Chapter 29 · Digital Health: Chatbots, Virtual Assistants, IoT, and Wearables","url":"read/ch-29.html#s-29-6","text":"List four chatbot use cases and the two constraints that keep them safe. Draw the IoT monitoring architecture and name two AI roles in it. Why does the AF-detection template say \"screening claims live or die after the flag\"? The official question bank for this unit — 18 questions with full model answers — is in Appendix D of this book."},{"type":"chapter","title":"Bioethical Principles and Ethical Frameworks for Healthcare AI","kicker":"Unit V · Chapter 30","url":"read/ch-30.html","text":"State the four bioethical principles and apply each to an AI system. 30.1 Chapter objectives 30.2 The four principles, applied to AI 30.3 AI-specific ethical questions 30.4 Key terms 30.5 Review questions"},{"type":"section","title":"30.1 Chapter objectives","kicker":"Chapter 30 · Bioethical Principles and Ethical Frameworks for Healthcare AI","url":"read/ch-30.html#s-30-1","text":"State the four bioethical principles and apply each to an AI system. Use structured ethical analysis (benefit–harm, consent, accountability) on a concrete deployment. Recognize the ethical questions unique to AI: consent for data reuse, accountability gaps, and autonomy erosion."},{"type":"section","title":"30.2 The four principles, applied to AI","kicker":"Chapter 30 · Bioethical Principles and Ethical Frameworks for Healthcare AI","url":"read/ch-30.html#s-30-2","text":"Principle Classical meaning AI application Characteristic failure Autonomy Patient's right to decide Meaningful consent for data use; explanation of AI involvement; opt-outs honored Black-box decisions patients cannot contest; hidden data reuse Beneficence Act for the patient's benefit Deploy only where benefit is demonstrated (local validation) Deploying for efficiency while care quality silently"},{"type":"section","title":"30.3 AI-specific ethical questions","kicker":"Chapter 30 · Bioethical Principles and Ethical Frameworks for Healthcare AI","url":"read/ch-30.html#s-30-3","text":"Consent for secondary data use. Patients consented to treatment, not to model training. Options: broad consent, opt-out registries, or consent waivers for de-identified research — each with an ethical cost, and each shaped by law (Chapter 32). The accountability gap. If an AI recommendation contributes to harm, who answers: the clinician who followed it, the hospital that deployed it, the vendor t"},{"type":"section","title":"30.4 Key terms","kicker":"Chapter 30 · Bioethical Principles and Ethical Frameworks for Healthcare AI","url":"read/ch-30.html#s-30-4","text":"Bioethical principles — autonomy, beneficence, non-maleficence, justice. Accountability gap — diffusion of responsibility for AI-influenced harm. Secondary data use — using care-generated data for model development. Automation bias (ethical view) — a transferred autonomy problem: the machine's framing silently narrows the clinician's."},{"type":"section","title":"30.5 Review questions","kicker":"Chapter 30 · Bioethical Principles and Ethical Frameworks for Healthcare AI","url":"read/ch-30.html#s-30-5","text":"Apply the four principles to an autonomous retinopathy screening program. Why is consent for secondary data use ethically distinct from consent for treatment? Explain the accountability gap and name the deployment-stage control that narrows it."},{"type":"chapter","title":"Bias, Fairness, and Health Equity","kicker":"Unit V · Chapter 31","url":"read/ch-31.html","text":"Trace the sources of bias from history to label to deployment. 31.1 Chapter objectives 31.2 Where bias enters 31.3 Fairness definitions — and the impossibility result 31.4 Mitigation across the lifecycle 31.5 Fairness audit as a deliverable 31.6 Key terms 31.7 Review questions"},{"type":"section","title":"31.1 Chapter objectives","kicker":"Chapter 31 · Bias, Fairness, and Health Equity","url":"read/ch-31.html#s-31-1","text":"Trace the sources of bias from history to label to deployment. State the formal fairness definitions and why they cannot all hold at once. Apply mitigation strategies and fairness audits across a model's lifecycle."},{"type":"section","title":"31.2 Where bias enters","kicker":"Chapter 31 · Bias, Fairness, and Health Equity","url":"read/ch-31.html#s-31-2","text":"Historical bias — the data records a biased world: referral patterns, access gaps, who got tested. A model predicting healthcare costs learned to under-predict the needs of Black patients who historically received less spending for equal illness (the widely cited Obermeyer et al., Science 2019 study — the fix was predicting need, not cost). Representation bias — subgroups absent or thin in trainin"},{"type":"section","title":"31.3 Fairness definitions — and the impossibility result","kicker":"Chapter 31 · Bias, Fairness, and Health Equity","url":"read/ch-31.html#s-31-3","text":"Group fairness: demographic parity (equal positive-prediction rates across groups); equalized odds (equal true-positive and false-positive rates); predictive parity/calibration within groups (equal PPV). Individual fairness: similar patients treated similarly. The theorem: under non-trivial conditions, calibration within groups and equalized odds cannot hold simultaneously (except in degenerate ca"},{"type":"section","title":"31.4 Mitigation across the lifecycle","kicker":"Chapter 31 · Bias, Fairness, and Health Equity","url":"read/ch-31.html#s-31-4","text":"Stage Techniques Pre-processing Re-weight/rebalance training data; targeted collection for thin subgroups; check label definitions for proxy bias In-processing Fairness-constrained training; adversarial debiasing Post-processing Group-specific thresholds (controversial — legal and ethical review required); calibrated score adjustment Process Disaggregated evaluation before and after deployment; bi"},{"type":"section","title":"31.5 Fairness audit as a deliverable","kicker":"Chapter 31 · Bias, Fairness, and Health Equity","url":"read/ch-31.html#s-31-5","text":"A clinical model ships with: subgroup sample counts; per-subgroup sensitivity, specificity, PPV, and calibration curves; the chosen fairness definition and why; known limitations; and a monitoring plan. This is the model-card content (Chapter 33) that fairness regulation (Chapter 32) increasingly expects."},{"type":"section","title":"31.6 Key terms","kicker":"Chapter 31 · Bias, Fairness, and Health Equity","url":"read/ch-31.html#s-31-6","text":"Demographic parity / equalized odds / calibration within groups — the three canonical group-fairness definitions. Impossibility result — calibration and equalized odds cannot both hold when base rates differ. Proxy variable bias — an allowed input (cost) standing in for a disallowed one (race, via spending patterns). Fairness audit — the documented, disaggregated evaluation shipped with a model."},{"type":"section","title":"31.7 Review questions","kicker":"Chapter 31 · Bias, Fairness, and Health Equity","url":"read/ch-31.html#s-31-7","text":"Reconstruct the Obermeyer cost-prediction finding: what was biased, and what was the fix? State the fairness impossibility result and its practical consequence. Why is \"remove race from the inputs\" an inadequate fairness strategy in healthcare?"},{"type":"chapter","title":"Regulatory Landscape: FDA, CE Marking, and SaMD","kicker":"Unit V · Chapter 32","url":"read/ch-32.html","text":"Define Software as a Medical Device (SaMD) and classify software by risk. 32.1 Chapter objectives 32.2 SaMD — the definition that decides everything 32.3 FDA pathways 32.4 CE marking and the EU MDR 32.5 Comparing the regimes and the shared lesson 32.6 Key terms 32.7 Review questions"},{"type":"section","title":"32.1 Chapter objectives","kicker":"Chapter 32 · Regulatory Landscape: FDA, CE Marking, and SaMD","url":"read/ch-32.html#s-32-1","text":"Define Software as a Medical Device (SaMD) and classify software by risk. Describe the FDA pathways (510(k), De Novo, PMA) and the adaptive ideas (predetermined change control plans). Describe CE marking under the EU MDR and compare the regimes."},{"type":"section","title":"32.2 SaMD — the definition that decides everything","kicker":"Chapter 32 · Regulatory Landscape: FDA, CE Marking, and SaMD","url":"read/ch-32.html#s-32-2","text":"Software as a Medical Device (SaMD) (IMDRF definition, adopted by regulators): software intended for a medical purpose that performs those purposes without being part of a hardware medical device . Classification turns on two axes — the criticality of the situation (serious vs non-serious) and the significance of the software's output (diagnose/treat vs triage/drive). A radiologist-facing triage t"},{"type":"section","title":"32.3 FDA pathways","kicker":"Chapter 32 · Regulatory Landscape: FDA, CE Marking, and SaMD","url":"read/ch-32.html#s-32-3","text":"Pathway Logic When used 510(k) Substantial equivalence to a legally marketed predicate device Most CAD/CDS imaging tools De Novo New device type, low–moderate risk, no predicate First-of-kind categories (IDx-DR used De Novo) PMA Highest-risk class III; clinical data required High-risk therapeutic/diagnostic AI FDA specifics for AI/ML: Predetermined Change Control Plans (PCCP) — the 2023+ guidance "},{"type":"section","title":"32.4 CE marking and the EU MDR","kicker":"Chapter 32 · Regulatory Landscape: FDA, CE Marking, and SaMD","url":"read/ch-32.html#s-32-4","text":"Under the EU Medical Device Regulation (MDR, 2017/745) , software with a medical purpose is a device and needs CE marking through a notified body, with clinical evidence proportionate to class (I → IIa → IIb → III). Requirements include clinical evaluation, post-market surveillance, and — for software — specific documentation (intended purpose, benefit–risk, usability). The EU AI Act layers on top"},{"type":"section","title":"32.5 Comparing the regimes and the shared lesson","kicker":"Chapter 32 · Regulatory Landscape: FDA, CE Marking, and SaMD","url":"read/ch-32.html#s-32-5","text":"Dimension FDA (US) EU MDR/AI Act Mechanism Risk-based pathways; predicate system Class-based conformity assessment via notified bodies Adaptation PCCP for planned updates Change requires re-assessment; surveillance duties Ongoing oversight Post-market surveillance; device list Post-market surveillance; vigilance reporting Shared lesson: regulators approve claims , not models — the intended use, th"},{"type":"section","title":"32.6 Key terms","kicker":"Chapter 32 · Regulatory Landscape: FDA, CE Marking, and SaMD","url":"read/ch-32.html#s-32-6","text":"SaMD — software with a medical purpose, not part of a hardware device. 510(k) / De Novo / PMA — FDA's three main pathways. PCCP — Predetermined Change Control Plan: pre-authorized update protocol. CE marking / MDR — EU conformity regime for medical devices. Intended use — the claim the authorization covers; the boundary of lawful deployment."},{"type":"section","title":"32.7 Review questions","kicker":"Chapter 32 · Regulatory Landscape: FDA, CE Marking, and SaMD","url":"read/ch-32.html#s-32-7","text":"Classify: (a) a worklist-triage hemorrhage tool; (b) an autonomous DR screener. Which pathways fit? What problem does a Predetermined Change Control Plan solve, and what does it pre-authorize? Why is \"intended use\" the most important field in a SaMD authorization?"},{"type":"chapter","title":"Responsible Deployment and Governance","kicker":"Unit V · Chapter 33","url":"read/ch-33.html","text":"Design a deployment plan: local validation, shadow mode, staged rollout. 33.1 Chapter objectives 33.2 The deployment plan 33.3 Post-deployment monitoring 33.4 Governance artifacts and structure 33.5 Key terms 33.6 Review questions"},{"type":"section","title":"33.1 Chapter objectives","kicker":"Chapter 33 · Responsible Deployment and Governance","url":"read/ch-33.html#s-33-1","text":"Design a deployment plan: local validation, shadow mode, staged rollout. Implement post-deployment monitoring for drift, performance, and equity. Define the governance structure: model cards, incident reporting, review boards, liability."},{"type":"section","title":"33.2 The deployment plan","kicker":"Chapter 33 · Responsible Deployment and Governance","url":"read/ch-33.html#s-33-2","text":"Local validation before any live use — re-evaluate the model on this hospital's data (different demographics, coding practice, devices). Performance transfer is the exception; verify it. Shadow mode — run silently alongside care; compare model behavior to actual clinical outcomes and workflow fit; tune thresholds on local operating characteristics. Staged rollout — one unit, then a service, then t"},{"type":"section","title":"33.3 Post-deployment monitoring","kicker":"Chapter 33 · Responsible Deployment and Governance","url":"read/ch-33.html#s-33-3","text":"Data drift — input distributions shift (new lab analyzers, new EHR version, new referral pattern); monitored by distribution tests on features. Concept drift — the outcome relationship changes (new treatment guidelines, a pandemic); monitored by outcome-linked performance on prospectively labeled samples. Equity monitoring — per-subgroup performance dashboards, because drift is rarely uniform. Inc"},{"type":"section","title":"33.4 Governance artifacts and structure","kicker":"Chapter 33 · Responsible Deployment and Governance","url":"read/ch-33.html#s-33-4","text":"Model cards / technical documentation — intended use, training data provenance, evaluation (including subgroup), operating point, known limitations, update history. Governance committee — clinical, data-science, informatics, ethics, and legal membership; owns go/no-go decisions, threshold changes, and retirement decisions. Versioning and reproducibility — every deployed decision traceable to a spe"},{"type":"section","title":"33.5 Key terms","kicker":"Chapter 33 · Responsible Deployment and Governance","url":"read/ch-33.html#s-33-5","text":"Local validation — re-evaluation of a model on the deploying institution's data. Shadow mode — silent parallel running before live use. Data drift / concept drift — input-distribution shift / outcome-relationship shift. Model card — standardized documentation of a model's intended use, data, and performance. Model governance committee — the cross-functional body owning deployment decisions."},{"type":"section","title":"33.6 Review questions","kicker":"Chapter 33 · Responsible Deployment and Governance","url":"read/ch-33.html#s-33-6","text":"Give three reasons a model with strong published external validation still needs local validation. Distinguish data drift and concept drift with one clinical example each. List the minimum fields of a model card for a deployed sepsis model."},{"type":"chapter","title":"Explainable AI and Building Clinical Trust","kicker":"Unit V · Chapter 34","url":"read/ch-34.html","text":"Distinguish trust, calibrated trust, and automation bias/under-trust. 34.1 Chapter objectives 34.2 The trust landscape 34.3 Designing the explanation artifact 34.4 When explanations mislead 34.5 Key terms 34.6 Review questions"},{"type":"section","title":"34.1 Chapter objectives","kicker":"Chapter 34 · Explainable AI and Building Clinical Trust","url":"read/ch-34.html#s-34-1","text":"Distinguish trust, calibrated trust, and automation bias/under-trust. Design explanations that support the clinical decision instead of decorating the score. Recognize explanation limits: attribution ≠ causation, instability, and gaming."},{"type":"section","title":"34.2 The trust landscape","kicker":"Chapter 34 · Explainable AI and Building Clinical Trust","url":"read/ch-34.html#s-34-2","text":"Over-trust (automation bias): the clinician stops checking; model errors pass through. Safeguards: confidence display with uncertainty, mandatory confirmation steps for high-stakes actions, periodic \"challenge\" audits. Under-trust: early failures or opaque reasoning cause wholesale disuse of a useful tool. Safeguards: honest failure reporting, explanations, and gradual responsibility transfer as e"},{"type":"section","title":"34.3 Designing the explanation artifact","kicker":"Chapter 34 · Explainable AI and Building Clinical Trust","url":"read/ch-34.html#s-34-3","text":"For a deployed clinical score, the usable artifact carries (Chapter 21's components, now as design requirements): The calibrated score with an uncertainty band. Top attributions in plain clinical language (\"elevated lactate, rising over 6 h — pushed score up strongly\"). Similar past cases and their outcomes. A counterfactual where one exists (\"if cultures drawn on arrival, score would have been hi"},{"type":"section","title":"34.4 When explanations mislead","kicker":"Chapter 34 · Explainable AI and Building Clinical Trust","url":"read/ch-34.html#s-34-4","text":"Unfaithful explanations (LIME instability across seeds), plausible-sounding attributions that the model does not actually depend on, explanation gaming (models rewarding shortcut features that produce convincing narratives), and the human tendency to accept any fluent reason (the same automation bias in a new costume). Governance (Chapter 33) answers with faithfulness checks and periodic review of"},{"type":"section","title":"34.5 Key terms","kicker":"Chapter 34 · Explainable AI and Building Clinical Trust","url":"read/ch-34.html#s-34-5","text":"Calibrated trust — trust matched to measured, local, per-subgroup reliability. Automation bias safeguard — interface/process controls that keep human checking alive. Explanation artifact — the designed package: score, attributions, similar cases, counterfactual, limitations. Faithfulness — the degree to which an explanation reflects the model's actual computation."},{"type":"section","title":"34.6 Review questions","kicker":"Chapter 34 · Explainable AI and Building Clinical Trust","url":"read/ch-34.html#s-34-6","text":"Define calibrated trust and state how you would measure it in a live radiology workflow. Assemble the five components of a clinical explanation artifact for an ECG-alert model. Give two ways an explanation can be unfaithful, and one governance control for each."},{"type":"chapter","title":"Federated Learning and Privacy-Preserving AI","kicker":"Unit V · Chapter 35","url":"read/ch-35.html","text":"Explain federated learning's training loop and the FedAvg protocol. 35.1 Chapter objectives 35.2 The federated training loop 35.3 Cross-silo vs cross-device; the hard problems 35.4 The honest threat model 35.5 Key terms 35.6 Review questions"},{"type":"section","title":"35.1 Chapter objectives","kicker":"Chapter 35 · Federated Learning and Privacy-Preserving AI","url":"read/ch-35.html#s-35-1","text":"Explain federated learning's training loop and the FedAvg protocol. Distinguish cross-silo and cross-device settings and their challenges (non-IID data above all). Combine FL with secure aggregation and differential privacy into an honest threat model."},{"type":"section","title":"35.2 The federated training loop","kicker":"Chapter 35 · Federated Learning and Privacy-Preserving AI","url":"read/ch-35.html#s-35-2","text":"A coordinating server distributes the current global model to participating sites. Each site trains locally on its own patients (data never moves). Sites return only model updates (gradients/weights). The server averages them ( FedAvg — typically weighted by site dataset size) into a new global model. Repeat for rounds until convergence; then validate, and deploy per the governance of Chapter 33. "},{"type":"section","title":"35.3 Cross-silo vs cross-device; the hard problems","kicker":"Chapter 35 · Federated Learning and Privacy-Preserving AI","url":"read/ch-35.html#s-35-3","text":"Cross-silo (a few hospitals or research centers; reliable, high-capacity participants) is the healthcare standard — e.g., multi-institution model consortia. Cross-device (thousands of phones/wearables) has unreliable participants and tiny per-device data. Non-IID data: each hospital's population, coding practice, and devices differ, so local updates differ from the global distribution; naive avera"},{"type":"section","title":"35.4 The honest threat model","kicker":"Chapter 35 · Federated Learning and Privacy-Preserving AI","url":"read/ch-35.html#s-35-4","text":"Model updates can leak information (gradient-inversion attacks can reconstruct inputs from naive gradient sharing; membership-inference attacks test whether a patient was in training). Defenses, combined: Secure aggregation — the server sees only the sum of updates, never individual updates (cryptographic masking). Differential privacy — noise added to updates, bounding any single patient's influe"},{"type":"section","title":"35.5 Key terms","kicker":"Chapter 35 · Federated Learning and Privacy-Preserving AI","url":"read/ch-35.html#s-35-5","text":"Federated learning / FedAvg — decentralized training / weight-by-size averaging of local updates. Cross-silo / cross-device — few reliable institutions / many unreliable endpoints. Non-IID federation — sites with differing data distributions. Secure aggregation — server sees sums, not individual updates. Differential privacy (ε) — bounded influence of any one patient, bought with noise."},{"type":"section","title":"35.6 Review questions","kicker":"Chapter 35 · Federated Learning and Privacy-Preserving AI","url":"read/ch-35.html#s-35-6","text":"Write the five steps of the FedAvg loop and state where patient data physically travels. Why is non-IID the defining challenge of healthcare federation, and what are two remedies? Name two attacks on federated updates and one defense against each."},{"type":"chapter","title":"Clinical Validation, Trials, and the Future of Healthcare AI","kicker":"Unit V · Chapter 36","url":"read/ch-36.html","text":"Distinguish retrospective validation from prospective and randomized evaluation of AI. 36.1 Chapter objectives 36.2 The evidence ladder 36.3 Landmark trials and their lessons 36.4 The future, honestly 36.5 Key terms 36.6 Review questions"},{"type":"section","title":"36.1 Chapter objectives","kicker":"Chapter 36 · Clinical Validation, Trials, and the Future of Healthcare AI","url":"read/ch-36.html#s-36-1","text":"Distinguish retrospective validation from prospective and randomized evaluation of AI. Describe landmark AI trials and the design questions they settle. Map the future: foundation models, multimodal agents, and the governance they demand."},{"type":"section","title":"36.2 The evidence ladder","kicker":"Chapter 36 · Clinical Validation, Trials, and the Future of Healthcare AI","url":"read/ch-36.html#s-36-2","text":"Retrospective validation — model vs archived labels; necessary, weak (selection and label effects). Prospective validation — model runs in live care, but decisions remain clinician-made; tests shift and workflow. Randomized controlled trials (RCTs) — patients or encounters randomized to AI-assisted vs usual care; the only design that isolates the AI's effect . Key variants: superiority vs non-infe"},{"type":"section","title":"36.3 Landmark trials and their lessons","kicker":"Chapter 36 · Clinical Validation, Trials, and the Future of Healthcare AI","url":"read/ch-36.html#s-36-3","text":"Colonoscopy (CADe): multiple RCTs showed AI-assisted colonoscopy increases adenoma detection rates — the strongest real-outcome evidence for medical imaging AI, with a caution: detection gains can fade as endoscopists adapt, and cluster designs matter. Mammography (MASAI, Sweden): AI-supported screening was non-inferior on cancer detection with materially reduced screen-reading workload — a worklo"},{"type":"section","title":"36.4 The future, honestly","kicker":"Chapter 36 · Clinical Validation, Trials, and the Future of Healthcare AI","url":"read/ch-36.html#s-36-4","text":"Foundation models for medicine: large multimodal models pre-trained across imaging, notes, and genomics, adapted to many tasks — promising for annotation efficiency and generalist reasoning; demanding on validation, bias, and regulation ( Chapters 31–33). Ambient clinical intelligence: documentation and summarization agents already in clinics; their risks are accuracy, PHI handling, and note-truth"},{"type":"section","title":"36.5 Key terms","kicker":"Chapter 36 · Clinical Validation, Trials, and the Future of Healthcare AI","url":"read/ch-36.html#s-36-5","text":"Prospective vs retrospective validation — live-care evaluation vs archived-label evaluation. Cluster randomization — randomizing by clinician/unit to avoid contamination. Non-inferiority trial — showing the AI-assisted pathway is not meaningfully worse. Foundation model — a large pre-trained multimodal model adapted to many downstream tasks. Endpoint–claim match — the trial must test the specific "},{"type":"section","title":"36.6 Review questions","kicker":"Chapter 36 · Clinical Validation, Trials, and the Future of Healthcare AI","url":"read/ch-36.html#s-36-6","text":"Why can retrospective validation never settle an outcome claim? What did the colonoscopy CADe trials and MASAI each prove — and what does each not prove? Name three future directions and one governance demand each creates. The official question bank for this unit — 18 questions with full model answers — is in Appendix D of this book."},{"type":"glossary","title":"AI in Healthcare","kicker":"A.1 · Foundations and Clinical Systems","url":"glossary.html#g-ai-in-healthcare","text":"computational systems that learn from clinical data to support medical decisions."},{"type":"glossary","title":"Machine learning (ML)","kicker":"A.1 · Foundations and Clinical Systems","url":"glossary.html#g-machine-learning-ml","text":"algorithms that infer patterns from data rather than following hand-coded rules."},{"type":"glossary","title":"Deep learning","kicker":"A.1 · Foundations and Clinical Systems","url":"glossary.html#g-deep-learning","text":"multi-layer neural networks that learn features from raw data such as pixels, waveforms, or text."},{"type":"glossary","title":"CDSS","kicker":"A.1 · Foundations and Clinical Systems","url":"glossary.html#g-cdss","text":"clinical decision support system: software combining patient data and medical knowledge into point-of-care advice."},{"type":"glossary","title":"Knowledge base","kicker":"A.1 · Foundations and Clinical Systems","url":"glossary.html#g-knowledge-base","text":"the computable medical knowledge inside a CDSS: rules, drug tables, or learned model parameters."},{"type":"glossary","title":"Inference engine","kicker":"A.1 · Foundations and Clinical Systems","url":"glossary.html#g-inference-engine","text":"the CDSS component that applies the knowledge base to a specific patient's data."},{"type":"glossary","title":"Five rights of CDS","kicker":"A.1 · Foundations and Clinical Systems","url":"glossary.html#g-five-rights-of-cds","text":"right information, person, format, channel, and time for decision support."},{"type":"glossary","title":"Alert fatigue","kicker":"A.1 · Foundations and Clinical Systems","url":"glossary.html#g-alert-fatigue","text":"desensitization caused by excessive low-value alerts."},{"type":"glossary","title":"MYCIN","kicker":"A.1 · Foundations and Clinical Systems","url":"glossary.html#g-mycin","text":"the 1970s rule-based expert system for antibiotic selection; accurate but never deployed."},{"type":"glossary","title":"IDx-DR","kicker":"A.1 · Foundations and Clinical Systems","url":"glossary.html#g-idx-dr","text":"the first FDA-authorized autonomous diagnostic AI (diabetic retinopathy, 2018)."},{"type":"glossary","title":"Telemedicine","kicker":"A.1 · Foundations and Clinical Systems","url":"glossary.html#g-telemedicine","text":"remote clinical care via telecommunications, synchronous or store-and-forward."},{"type":"glossary","title":"RPM","kicker":"A.1 · Foundations and Clinical Systems","url":"glossary.html#g-rpm","text":"remote patient monitoring: device-streamed vitals with algorithmic escalation."},{"type":"glossary","title":"Ambient documentation","kicker":"A.1 · Foundations and Clinical Systems","url":"glossary.html#g-ambient-documentation","text":"AI-generated visit notes drafted from the consultation audio."},{"type":"glossary","title":"EHR","kicker":"A.2 · Data, Standards, and Coding","url":"glossary.html#g-ehr","text":"longitudinal, computable digital record of patient encounters, orders, results, and medications."},{"type":"glossary","title":"Computability","kicker":"A.2 · Data, Standards, and Coding","url":"glossary.html#g-computability","text":"the property that data can be queried and processed algorithmically, not just read."},{"type":"glossary","title":"Copy-forward","kicker":"A.2 · Data, Standards, and Coding","url":"glossary.html#g-copy-forward","text":"copying prior note text forward, propagating stale information."},{"type":"glossary","title":"HL7 FHIR","kicker":"A.2 · Data, Standards, and Coding","url":"glossary.html#g-hl7-fhir","text":"modern web-style clinical data exchange standard built on discrete resources."},{"type":"glossary","title":"DICOM","kicker":"A.2 · Data, Standards, and Coding","url":"glossary.html#g-dicom","text":"the medical imaging data standard: pixels plus a rich metadata header."},{"type":"glossary","title":"PACS","kicker":"A.2 · Data, Standards, and Coding","url":"glossary.html#g-pacs","text":"picture archiving and communication system; the imaging archive."},{"type":"glossary","title":"FASTQ","kicker":"A.2 · Data, Standards, and Coding","url":"glossary.html#g-fastq","text":"raw sequencing reads with per-base quality scores."},{"type":"glossary","title":"VCF","kicker":"A.2 · Data, Standards, and Coding","url":"glossary.html#g-vcf","text":"variant call format: called genomic variants per patient."},{"type":"glossary","title":"ECG / EEG / PPG","kicker":"A.2 · Data, Standards, and Coding","url":"glossary.html#g-ecg-eeg-ppg","text":"heart electrical, brain electrical, and pulse waveform signals."},{"type":"glossary","title":"ICD-10-CM","kicker":"A.2 · Data, Standards, and Coding","url":"glossary.html#g-icd-10-cm","text":"diagnostic classification system (WHO standard, national clinical modification)."},{"type":"glossary","title":"CPT","kicker":"A.2 · Data, Standards, and Coding","url":"glossary.html#g-cpt","text":"AMA-maintained terminology for procedures and services."},{"type":"glossary","title":"SNOMED CT / LOINC / RxNorm","kicker":"A.2 · Data, Standards, and Coding","url":"glossary.html#g-snomed-ct-loinc-rxnorm","text":"terminologies for clinical terms, lab observations, and medications."},{"type":"glossary","title":"Code as proxy","kicker":"A.2 · Data, Standards, and Coding","url":"glossary.html#g-code-as-proxy","text":"using billing codes as ML labels despite their coding-practice bias."},{"type":"glossary","title":"Data cleaning","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-data-cleaning","text":"detecting and correcting errors and inconsistencies so records reflect clinical reality."},{"type":"glossary","title":"Normalization","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-normalization","text":"rescaling features to a bounded range (min–max)."},{"type":"glossary","title":"Standardization","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-standardization","text":"rescaling to zero mean and unit variance (z-score)."},{"type":"glossary","title":"MCAR / MAR / MNAR","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-mcar-mar-mnar","text":"missingness mechanisms: unrelated, explained by observed data, or tied to the missing value itself."},{"type":"glossary","title":"Imputation","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-imputation","text":"filling missing values with estimates (median, KNN, MICE)."},{"type":"glossary","title":"MICE","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-mice","text":"multiple imputation by chained equations; the principled MAR method."},{"type":"glossary","title":"Missingness indicator","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-missingness-indicator","text":"a binary feature recording that a value was absent."},{"type":"glossary","title":"Selection bias","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-selection-bias","text":"a training sample differing systematically from the target population."},{"type":"glossary","title":"Feature engineering","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-feature-engineering","text":"constructing model inputs that encode clinical meaning."},{"type":"glossary","title":"Comorbidity index","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-comorbidity-index","text":"a validated summary of disease burden (Charlson, Elixhauser)."},{"type":"glossary","title":"Observation window","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-observation-window","text":"the time interval whose data is allowed into features."},{"type":"glossary","title":"Leakage","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-leakage","text":"information in training features that would not be available at prediction time."},{"type":"glossary","title":"HRV","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-hrv","text":"heart-rate variability features (RMSSD, SDNN) reflecting autonomic state."},{"type":"glossary","title":"Morphology features","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-morphology-features","text":"shape descriptors of a waveform (intervals, amplitudes, band powers)."},{"type":"glossary","title":"LASSO","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-lasso","text":"L1-regularized regression performing embedded feature selection."},{"type":"glossary","title":"PCA","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-pca","text":"linear projection maximizing retained variance."},{"type":"glossary","title":"NER","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-ner","text":"named entity recognition: tagging clinical concepts in text."},{"type":"glossary","title":"Negation/assertion detection","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-negation-assertion-detection","text":"deciding whether an extracted concept is present, absent, or uncertain."},{"type":"glossary","title":"UMLS","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-umls","text":"the Unified Medical Language System metathesaurus linking clinical vocabularies."},{"type":"glossary","title":"Auto-coding","kicker":"A.3 · Preprocessing and Features","url":"glossary.html#g-auto-coding","text":"NLP-driven assignment of billing/diagnosis codes from clinical text."},{"type":"glossary","title":"Supervised learning","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-supervised-learning","text":"learning from labeled examples to predict defined targets."},{"type":"glossary","title":"Unsupervised learning","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-unsupervised-learning","text":"discovering structure (clusters, anomalies) without labels."},{"type":"glossary","title":"Phenotyping","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-phenotyping","text":"deriving patient subtypes from data."},{"type":"glossary","title":"Risk prediction","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-risk-prediction","text":"supervised prediction of a future clinical event."},{"type":"glossary","title":"Time-zero","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-time-zero","text":"the defined moment from which features are measured."},{"type":"glossary","title":"Calibration","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-calibration","text":"agreement between predicted probabilities and observed frequencies."},{"type":"glossary","title":"Sensitivity / specificity","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-sensitivity-specificity","text":"recall on positives / recall on negatives."},{"type":"glossary","title":"PPV / NPV","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-ppv-npv","text":"positive and negative predictive values; prevalence-dependent."},{"type":"glossary","title":"AUC-ROC / AUPRC","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-auc-roc-auprc","text":"area under the ROC curve / precision-recall curve."},{"type":"glossary","title":"Base-rate trap","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-base-rate-trap","text":"ROC-AUC flattering a model at low prevalence."},{"type":"glossary","title":"Operating point","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-operating-point","text":"the threshold chosen for deployment by clinical cost."},{"type":"glossary","title":"Class imbalance","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-class-imbalance","text":"positive prevalence far below 50%."},{"type":"glossary","title":"SMOTE","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-smote","text":"synthetic minority oversampling by interpolation."},{"type":"glossary","title":"Focal loss","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-focal-loss","text":"loss down-weighting easy examples to focus on hard ones."},{"type":"glossary","title":"LIME","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-lime","text":"local surrogate explanation by perturbation."},{"type":"glossary","title":"SHAP / Shapley value","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-shap-shapley-value","text":"game-theoretic average marginal contribution per feature."},{"type":"glossary","title":"TreeSHAP","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-treeshap","text":"exact, fast SHAP for tree ensembles."},{"type":"glossary","title":"Grad-CAM","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-grad-cam","text":"class-activation map showing where an imaging model looked."},{"type":"glossary","title":"CNN","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-cnn","text":"convolutional neural network; learned local filters for images."},{"type":"glossary","title":"Transfer learning","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-transfer-learning","text":"reusing pretrained representations for a new task."},{"type":"glossary","title":"LSTM / GRU","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-lstm-gru","text":"gated recurrent architectures for sequences."},{"type":"glossary","title":"U-Net","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-u-net","text":"encoder–decoder segmentation network with skip connections."},{"type":"glossary","title":"Dice coefficient","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-dice-coefficient","text":"segmentation overlap metric: 2|A∩B|/(|A|+|B|)."},{"type":"glossary","title":"External validation","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-external-validation","text":"evaluation on data from a different population or institution."},{"type":"glossary","title":"MIMIC-III/IV","kicker":"A.4 · Modeling and Evaluation","url":"glossary.html#g-mimic-iii-iv","text":"de-identified critical-care benchmark datasets."},{"type":"glossary","title":"WSI","kicker":"A.5 · Imaging, Signals, and Genomics","url":"glossary.html#g-wsi","text":"whole-slide imaging: gigapixel digital scan of a pathology slide."},{"type":"glossary","title":"Gleason grading","kicker":"A.5 · Imaging, Signals, and Genomics","url":"glossary.html#g-gleason-grading","text":"prostate cancer aggressiveness grading from tissue architecture."},{"type":"glossary","title":"CADe / CADx","kicker":"A.5 · Imaging, Signals, and Genomics","url":"glossary.html#g-cade-cadx","text":"computer-aided detection / diagnosis."},{"type":"glossary","title":"Segmentation","kicker":"A.5 · Imaging, Signals, and Genomics","url":"glossary.html#g-segmentation","text":"pixel- or voxel-level delineation of a structure."},{"type":"glossary","title":"Multi-modal fusion","kicker":"A.5 · Imaging, Signals, and Genomics","url":"glossary.html#g-multi-modal-fusion","text":"combining imaging, labs, notes, and signals in one model."},{"type":"glossary","title":"Polygenic risk score (PRS)","kicker":"A.5 · Imaging, Signals, and Genomics","url":"glossary.html#g-polygenic-risk-score-prs","text":"weighted aggregate of common-variant genetic risk."},{"type":"glossary","title":"Pharmacogenomics","kicker":"A.5 · Imaging, Signals, and Genomics","url":"glossary.html#g-pharmacogenomics","text":"genotype-guided drug selection and dosing."},{"type":"glossary","title":"Precision oncology","kicker":"A.5 · Imaging, Signals, and Genomics","url":"glossary.html#g-precision-oncology","text":"therapy selection driven by a tumor's molecular profile."},{"type":"glossary","title":"Virtual screening","kicker":"A.5 · Imaging, Signals, and Genomics","url":"glossary.html#g-virtual-screening","text":"ML-predicted prioritization of compound libraries."},{"type":"glossary","title":"QSAR","kicker":"A.5 · Imaging, Signals, and Genomics","url":"glossary.html#g-qsar","text":"quantitative structure–activity relationship: property prediction from molecular structure."},{"type":"glossary","title":"Drug repurposing","kicker":"A.5 · Imaging, Signals, and Genomics","url":"glossary.html#g-drug-repurposing","text":"finding new uses for approved drugs (signature reversal, knowledge graphs)."},{"type":"glossary","title":"CGM","kicker":"A.5 · Imaging, Signals, and Genomics","url":"glossary.html#g-cgm","text":"continuous glucose monitoring."},{"type":"glossary","title":"Bioethical principles","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-bioethical-principles","text":"autonomy, beneficence, non-maleficence, justice."},{"type":"glossary","title":"Accountability gap","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-accountability-gap","text":"diffusion of responsibility for AI-influenced harm."},{"type":"glossary","title":"Automation bias","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-automation-bias","text":"over-trusting machine output and stopping independent checking."},{"type":"glossary","title":"Demographic parity / equalized odds / calibration within groups","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-demographic-parity-equalized-odds-calibration-wi","text":"canonical group-fairness definitions."},{"type":"glossary","title":"Fairness audit","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-fairness-audit","text":"documented, disaggregated evaluation shipped with a model."},{"type":"glossary","title":"SaMD","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-samd","text":"software as a medical device: software with a medical purpose, not part of a hardware device."},{"type":"glossary","title":"510(k) / De Novo / PMA","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-510-k-de-novo-pma","text":"the FDA's main approval pathways."},{"type":"glossary","title":"PCCP","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-pccp","text":"predetermined change control plan: pre-authorized protocol for model updates."},{"type":"glossary","title":"CE marking / MDR","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-ce-marking-mdr","text":"the EU conformity regime for medical devices."},{"type":"glossary","title":"Intended use","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-intended-use","text":"the claim an authorization covers; the boundary of lawful deployment."},{"type":"glossary","title":"Local validation","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-local-validation","text":"re-evaluation of a model on the deploying institution's data."},{"type":"glossary","title":"Shadow mode","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-shadow-mode","text":"silent parallel running of a model before live use."},{"type":"glossary","title":"Data drift / concept drift","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-data-drift-concept-drift","text":"input-distribution shift / outcome-relationship shift."},{"type":"glossary","title":"Model card","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-model-card","text":"standardized documentation of intended use, data, performance, and limitations."},{"type":"glossary","title":"Calibrated trust","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-calibrated-trust","text":"trust matched to measured, local, per-subgroup reliability."},{"type":"glossary","title":"Federated learning / FedAvg","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-federated-learning-fedavg","text":"decentralized training / weighted averaging of local model updates."},{"type":"glossary","title":"Cross-silo / cross-device","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-cross-silo-cross-device","text":"federation across a few institutions / many unreliable endpoints."},{"type":"glossary","title":"Secure aggregation","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-secure-aggregation","text":"protocol where the server sees only the sum of updates."},{"type":"glossary","title":"Differential privacy (ε)","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-differential-privacy","text":"bounded influence of any one patient, bought with noise."},{"type":"glossary","title":"PHI","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-phi","text":"protected health information; health data linked to identifiers."},{"type":"glossary","title":"BAA","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-baa","text":"business associate agreement with any vendor processing PHI."},{"type":"glossary","title":"Safe Harbor / Expert Determination","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-safe-harbor-expert-determination","text":"HIPAA's two de-identification standards."},{"type":"glossary","title":"Endpoint–claim match","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-endpoint-claim-match","text":"the trial must test the specific claim being made."},{"type":"glossary","title":"Cluster randomization","kicker":"A.6 · Ethics, Regulation, and Trust","url":"glossary.html#g-cluster-randomization","text":"randomizing by clinician or unit to avoid contamination in AI trials."},{"type":"lab","title":"Lab 1. Map a Clinical Data Ecosystem","kicker":"Chapters Ch. 1–8","url":"labs.html#lab-1","text":"Objective: connect the abstract data ecosystem of Unit I to one concrete clinical workflow. Steps: Choose one workflow (stroke care, antenatal screening, or an ICU admission). Enumerate every data type it generates (stru"},{"type":"lab","title":"Lab 2. Clean a Messy Clinical Extract","kicker":"Chapters Ch. 9–10","url":"labs.html#lab-2","text":"Objective: practice the cleaning and missing-data discipline of Chapter 9–10 on a deliberately dirty dataset. Steps: Take a synthetic EHR extract (Synthea or a course-provided CSV) with mixed units, duplicates, and gaps."},{"type":"lab","title":"Lab 3. Engineer EHR Features Without Leakage","kicker":"Chapters Ch. 11–12","url":"labs.html#lab-3","text":"Objective: build a time-zeroed feature matrix for a readmission or deterioration target. Steps: Define time-zero and an observation window (e.g., first 24 h → predict the rest of the stay). Engineer at least six features"},{"type":"lab","title":"Lab 4. Clinical NLP: Negation and Auto-Coding","kicker":"Chapters Ch. 13–14","url":"labs.html#lab-4","text":"Objective: extract structured signals from clinical text without falling for its negations. Steps: Take 20–50 de-identified discharge summaries or radiology reports (course-provided or MIMIC-derived samples). Run a clini"},{"type":"lab","title":"Lab 5. Train and Evaluate an Imbalanced Risk Model","kicker":"Chapters Ch. 15–20","url":"labs.html#lab-5","text":"Objective: build an honest evaluation of a rare-event model, the core skill of Unit III. Steps: Use a dataset with low positive prevalence (e.g., ICU mortality or a rare-disease cohort). Train the model ladder: logistic "},{"type":"lab","title":"Lab 6. Transfer Learning and Segmentation on Medical Images","kicker":"Chapters Ch. 17, 24–25","url":"labs.html#lab-6","text":"Objective: fine-tune a pretrained CNN and run a U-Net segmentation, with attention checks. Steps: Fine-tune an ImageNet-pretrained ResNet/EfficientNet on a chest X-ray classification task (CheXpert sample or NIH sample)."},{"type":"lab","title":"Lab 7. Time-Series Deterioration Prediction","kicker":"Chapters Ch. 18, 26","url":"labs.html#lab-7","text":"Objective: build a sequence model on irregularly sampled ICU data. Steps: Extract vitals and labs for a cohort from MIMIC-III/IV or a provided extract; define time-zero and a prediction horizon. Build the input represent"},{"type":"lab","title":"Lab 8. Explanation, Fairness Audit, and Model Card","kicker":"Chapters Ch. 21, 30–35","url":"labs.html#lab-8","text":"Objective: ship the governance artifact for a model built in an earlier lab. Steps: Generate SHAP (TreeSHAP) attributions for the Lab 5 model; verify additivity on one patient. Compose the explanation artifact: score wit"},{"type":"page","title":"Appendix C. Further Reading and Primary Sources","kicker":"Reference","url":"reading.html","text":""},{"type":"page","title":"Appendix D. Question Bank with Model Answers","kicker":"Reference","url":"question-bank.html","text":""}];
